(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).zh={"nav.skip":"跳到正文","nav.main":"主导航","nav.menu":"菜单","nav.close":"关闭","nav.lang":"语言","nav.tick":"区块","nav.tick.title":"最新区块。打开实时网络页面。","cta.join":"参与","nav.g.part":"参与","nav.g.know":"了解","nav.g.join":"加入","nav.start":"从哪里开始","nav.start.d":"五条入门路径，每条都有第一步","nav.mine":"挖矿","nav.mine.d":"用手机、电脑或显卡寻找区块","nav.wallet":"钱包","nav.wallet.d":"只有你持有的十二个助记词","nav.node":"运行节点","nav.node.d":"亲自核实每个区块","nav.ysr":"YSR","nav.ysr.d":"2100 万枚，每一枚都由挖矿产生","nav.chain":"区块链","nav.chain.d":"一条独立的区块链，以及它如何自证","nav.network":"实时网络","nav.network.d":"这条链此刻正在做什么","nav.explorer":"区块浏览器","nav.explorer.d":"每个区块、每笔转账、每个地址","nav.community":"社区","nav.community.d":"项目讨论与决策的地方","nav.build":"开发","nav.build.d":"开放的代码、公开的 API、提案","nav.story":"历程与下一步","nav.story.d":"从区块 0 到今天，以及接下来的事","foot.claim":"从区块 0 起就公平。","foot.sub":"YSKAR 是一个社区项目。背后没有任何公司，你也不必相信任何人：每个区块都可以核实。","foot.nav":"所有页面","foot.whitepaper":"白皮书","foot.find":"在这些地方找到 YSKAR","foot.imprint":"网站信息","foot.privacy":"隐私政策","foot.license":"以 MIT 许可证开源","title.home":"从区块 0 起就公平","title.start":"从哪里开始","title.mine":"挖矿","title.wallet":"YSKAR Wallet","title.node":"运行节点","title.ysr":"YSR，这枚币","title.chain":"区块链","title.network":"实时网络","title.explorer":"区块浏览器","title.build":"在 YSKAR 上开发","title.community":"社区","title.story":"历程与下一步","ui.copied":"已复制","ui.copy":"复制","ui.sample":"屏幕上显示的是示例数据。","dawn.h":"这里天色尚早。","dawn.p":"第 <span data-live='day'></span> 天。第一缕光才刚刚照到这个网络上。塑造它的，正是此刻在这里的人。","dawn.cta2":"阅读迄今为止的历程","dawn.alt":"同一处峡湾，晨光初现：淡色的天空下是积雪的群山和平静的水面。","nav.guides":"教程","nav.guides.d":"每一种参与方式，一步一步来","nav.protocol":"协议","nav.protocol.d":"币、链与钱包，逐字节说明","nav.paper.d":"系统的实际实现","title.guides":"教程","title.protocol":"协议","title.paper":"白皮书","title.imprint":"网站信息","title.privacy":"隐私政策","doc.toc":"本页内容","foot.live":"这些页面上的数字实时读取自公开的 YSKAR API。","foot.stale":"公开的 YSKAR API 目前没有响应。这些页面显示的是 {date}（区块 {h}）时的链上状态，之后会自动跟上。","title.notfound":"未找到页面","nf.h":"这个页面不存在。","nf.p":"链接可能输错了，或者页面已经移动。链本身还在原来的地方。","nf.home":"前往首页","nf.explorer":"在区块浏览器中查找","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR 是一种拥有独立区块链的货币。没有任何预先分配：每一枚 YSR 都由挖矿产生，任何人都可以核实每个区块。从区块 0 起就公平。","home.hero.cta2":"查看迄今为止的链","home.hero.live":"第 {d} 天 · 区块 {h} · 岸边亮着 {n} 盏灯，每个报到的节点一盏","home.hero.alt":"星空下，积雪群山之间的一处幽暗峡湾。蓝色的光带在上空流动，远处岸边亮着点点暖光。","home.m1":"它不是从一个承诺开始的。它是从一个区块开始的。","home.m2":"没有任何预挖。没有任何预先分配。早期产生的约 107 万枚 YSR 已被销毁，以抵消先发优势。","home.m3":"从那以后，新的 YSR 只有一种方式来到世上：机器完成工作，任何人都可以核实。","walk.start.h":"<span data-live='day'></span> 天，一个区块接一个区块。","walk.start.p":"每一盏灯都是一个真实的区块，两盏灯之间的距离就是它们之间相隔的时间。滚动页面沿着链前行。点按一盏灯即可打开对应的区块。","walk.c0.h":"一切从一个区块开始。","walk.c0.p":"它唯一的留言是“proof, not promise”。它的 875 YSR 奖励进入了一个任何人都无法花费的地址。","walk.c1.h":"第一天：46 个区块。","walk.c1.p":"区块 0 之后的第一个区块出现在 18:03 UTC。到午夜时已有 46 个：这条链找到了自己的节奏。","walk.c3.h":"先发优势被销毁。","walk.c3.p":"早期产生的 1,066,101 YSR 被发送到那个任何人都无法花费的地址，以抵消先发优势。全部都在这个区块里。","walk.c4.h":"社区投票。","walk.c4.p":"修订版 6 是公开决定的：共享账户、时间锁、一次向一千个收款方付款。当时已有三次规则升级生效。","walk.c5.h":"你在这里。","walk.c5.p":"距离下一个区块大约还有十分钟。","walk.c6.h":"接下来：修订版 6 启用。","walk.c6.p":"还有 <span data-live='v6Left'></span> 个区块。每个节点都提前知道这个高度，所以不会有任何意外的变化。","walk.c6.h.past":"修订版 6 已生效。","walk.c6.p.past":"从区块 10,000 起，这条链支持共享账户、时间锁和批量付款。","walk.c7.h":"随后第一个纪元结束。","walk.c7.p":"在区块 12,000 之前，每个区块产生 875 YSR，之后为 437.5。未来存在的全部 YSR 中，有一半来自这第一个纪元。","walk.c7.h.past":"第一个纪元已经结束。","walk.c7.p.past":"从区块 12,000 起，每个区块产生 437.5 YSR。此后每 12,000 个区块奖励再减半一次。","walk.open":"打开这个区块","walk.k.block":"区块 {h} · {d}","walk.k.future":"区块 {h} · 尚未到来","home.walk.now":"区块 {h} · 第 {d} 天","walk.hud.block":"区块 {h}","walk.hud.ahead":"区块 {h}","walk.hud.planned":"尚未到来 · 已写入代码","walk.hud.day":"第 {n} 天","walk.tip.block":"区块 {h}","walk.tip.approx":"详情在区块浏览器中加载","walk.tip.solo":"由单个矿工找到","walk.tip.pool":"由矿池找到","walk.tip.tx":"包含转账","walk.legend.block":"一个区块","walk.legend.tx":"包含转账的区块","walk.canvas":"把这条链画成一条光带，自区块 0 起每个区块一盏灯。","home.proof.h":"不必只听我们说。","home.proof.p":"每个区块都自带证明。你的设备现在就可以核实它：不需要服务器，不需要账户，只需要算术。","prove.btn.genesis":"在这台设备上核实区块 0","prove.btn.tip":"核实最新区块","prove.label":"区块头的哈希","prove.ok":"有效。区块 {h} 已在这台设备上核实，用时 {ms} 毫秒。","prove.bad":"无效：区块 {h} 未达到目标值。","prove.open":"在区块浏览器中打开区块 {h}","prove.note":"你的设备刚刚做了什么：把区块头的 136 个字节用 SHA-256 计算了两次。结果必须小于网络为该区块设定的目标值。开头的零显示出它有多小。","home.ways.h":"三条入门路径。","home.ways.p":"YSKAR 的标志是三条交汇的光带。网络也是如此：挖矿的人、持有并发送的人，以及让节点保持运行的人。","way.mine.h":"把你的机器借给它。","way.mine.p":"手机、电脑或显卡都能找到区块。可以单独挖，也可以加入矿池，矿池直接在区块内向你支付，从不保管你的币。","way.mine.cta":"挖矿是如何运作的","way.mine.alt":"夜晚，木桌上的一台笔记本电脑正在运行 YSKAR Node Core；背后是一扇望向幽暗峡湾的窗户。","way.wallet.h":"十二个助记词。只属于你。","way.wallet.p":"你的钱包就在你自己的设备上。除你之外没有人持有你的私钥，包括开发 YSKAR 的人。","way.wallet.cta":"获取钱包","way.wallet.alt":"一部打开着 YSKAR Wallet 的手机放在深色木桌上，旁边是一本手写了十二行字的笔记本、一支笔和一杯茶。","way.node.h":"留一盏灯。","way.node.p":"节点会从区块 0 开始亲自核实每个区块。每多一个节点，网络就更难被左右。窗台上的一台小电脑就够了。","way.node.cta":"运行节点","way.node.alt":"木窗台上的一台小电脑，亮着一盏青色状态灯；窗外是夜色中的峡湾，远处岸边有几点灯光。","home.ways.more":"或者在它之上开发。代码是开放的，API 是公开的，提案在所有人都能看到的地方讨论。","home.ways.more.cta":"面向开发者","home.early.say":"第 {d} 天。{n} 个节点。{m} 位矿工。{p} 个矿池。{x} 笔转账。没有上市。没有价格。早期就是这个样子。","home.early.note":"节点和矿工的数量来自它们自己的上报。所有数字都来自公开的 API。","home.early.p":"一个小小的网络，诞生才 <span data-live='day'></span> 天。YSR 尚未在任何地方上市，也没有价格；上市正在筹备中，没有日期，也没有名称。今天已经有的，是一条正常运行的链、你可以运行的软件，以及留给此刻到来的人的空间。","home.era.h":"纪元 <span data-live='era'></span>","home.era.p":"在这个纪元里，每个区块产生 <span data-live='rewardNow'></span> YSR。到区块 <span data-live='halvingHeight'></span> 时奖励减半，此后每 12,000 个区块再减半一次。未来存在的全部 YSR 中，有一半来自最初的 12,000 个区块。这份时间表写在代码里，没有人能改动它。","home.era.now":"区块 <span data-live='height'></span>","home.era.left":"还剩 <span data-live='halvingLeft'></span> 个区块","home.era.cta":"完整的时间表","home.people.h":"没有公司。只有人。","home.people.p":"YSKAR 是一个社区项目，属于使用它的人。他们挖矿、运行节点、测试新版本，并公开决定各项变更：修订版 6 就交给了社区投票。","home.people.cta":"认识社区","home.people.cta2":"打开 YSKAR Lab","home.people.alt":"蓝调时分，积雪的岸边约有十五个人的背影，每人手里提着一盏小灯，望向峡湾。","start.h1":"选择你的入门路径。","start.lead":"参与不需要任何费用。从适合你的方式开始；之后同样的十二个助记词可以打开每一扇门。","start.1.h":"我想持有并发送 YSR","start.1.p":"安装安卓钱包，把十二个助记词写在纸上，出示你的地址。收款只需要这些。","start.1.do":"前往钱包","start.2.h":"我想挖矿","start.2.p":"从你已有的设备开始：电脑上用 Node Core，手机上用安卓应用，矿机上用命令行。","start.2.do":"前往挖矿","start.3.h":"我想亲自核实这条链","start.3.p":"运行一个节点。它会从区块 0 起验证每个区块，成为岸边多出的一盏灯。","start.3.do":"运行节点","start.4.h":"我想参与开发或提供帮助","start.4.p":"阅读代码，查询公开的 API，测试新版本，把提案带到 YSKAR Lab。","start.4.do":"面向开发者","start.5.h":"我暂时只想看看","start.5.p":"实时关注这条链，在区块浏览器中打开任意区块，在频道里看大家的讨论。","start.5.do":"实时网络","start.safe.h":"先了解三件事","start.alt.fjord":"星空下的一处幽暗峡湾。","mine.h1":"把你的机器借给它。","mine.lead":"新的 YSR 只来自挖矿，别无其他来源。手机、电脑或显卡都可以参与，单独挖或加入矿池。","mine.cta":"选择你的配置","mine.cta2":"就在这里试一试","mine.try.h":"挖矿就是猜数，而且猜得非常快。","mine.try.p":"按下开始，这台设备就会参与片刻。它取最新的区块，寻找一个能让哈希以足够多的零开头的数字：这与每个矿工进行的搜索相同，只是难度为练习难度。","mine.try.go":"开始猜","mine.try.stop":"停止","mine.try.again":"再来一次","mine.try.tries":"尝试次数","mine.try.speed":"速度","mine.try.idle":"还没有找到。每一点火花都是一批尝试。","mine.try.found":"尝试 {n} 次后找到了。","mine.try.none":"尝试了 {n} 次，没有运气。这也是挖矿。再试一次。","mine.try.real":"刚才只是练习。真实网络的难度是它的 {x} 倍：以 {r} 的速度，单靠这台设备找到一个真实区块大约需要 {t}。这就是矿工加入矿池的原因。","mine.try.canvas":"每一批尝试都迸出火花；找到有效数字时闪出一道亮光。","mine.setup.h":"选择你的配置","mine.calc.h":"你的机器能找到什么？","mine.pools.h":"实时矿池","wal.h1":"十二个助记词。只属于你。","wal.lead":"YSKAR Wallet 是 YSR 的安卓应用：发送、接收、签名。你的私钥在你的手机上生成，并留在那里。","wal.cta2":"四步完成安装","wal.say":"谁拥有这十二个助记词，谁就拥有资金。把它们写在纸上。YSKAR 的任何人都不会向你索要它们。","node.h1":"留一盏灯。","node.lead":"全节点从区块 0 起亲自核实每个区块，并把它转发出去。它不向任何人询问什么是真的。每一个这样做的节点，都让网络更难被左右。","node.cta":"获取 Node Core","node.cta2":"通过命令行","node.say":"这片岸边的每一盏灯都是一个已报到的节点。现在共有 {n} 盏。你的将是第 {k} 盏。","node.core.h":"Node Core：节点、钱包和挖矿程序，集于一个窗口。","node.core.p":"安装之后，你的电脑会自行验证这条链。Node Core 还保管你的钱包，用你的处理器或显卡挖矿，可以运行矿池，并能为消息签名。版本 1.1.0，适用于 Windows 10 和 11 以及 64 位 Linux。","node.dl.win":"Windows 安装程序","node.dl.deb":"Linux 软件包（.deb）","node.dl.app":"Linux AppImage","node.dl.get":"下载","node.dl.all":"所有文件和校验和","node.dl.rel":"GitHub 上的发布版本","node.why.h":"多一个节点会带来什么","node.w1.p":"你的节点从区块 0 开始重新计算工作量、签名和每一个余额。违反规则的区块会被拒绝，无论是谁发来的。","node.w2.h":"它支撑着网络","node.w2.p":"每个节点都把区块和转账转发给其他节点。节点越多、分布越广，网络就越不依赖任何一台机器。","node.w3.h":"它的要求很低","node.w3.p":"通过命令行，节点可以在 Linux、Windows 和 macOS 上运行，甚至可以在树莓派上运行。桌面应用 Node Core 可在 Windows 和 64 位 Linux 上运行。","coin.h1":"2100 万枚。每一枚都由挖矿产生。","coin.lead":"YSR 是 YSKAR 链的币。总量永远不会超过 21,000,000 枚。没有预挖，也没有预先分配：新的 YSR 只因一个原因而存在，那就是找到了一个区块。","coin.alt":"YSR 币：一枚厚实的蓝色玻璃圆盘，边缘凸起，带有浮雕的 YSKAR 标志。","coin.alt.flat":"YSR 币：一枚带蓝色圆环和 YSKAR 标志的深色圆盘。","coin.bar.mined":"迄今已挖出","coin.bar.burned":"其中已销毁或无法花费","coin.bar.open":"尚待挖出","coin.eras.h":"奖励每 12,000 个区块减半一次。","coin.eras.p":"每一条柱代表一个纪元，显示该纪元产生多少 YSR。仅第一个纪元就产生了总量的一半。最后一枚新的 YSR 出现在区块 443,999；此后矿工只赚取手续费。","coin.eras.era":"纪元 {n}","coin.eras.now":"当前","coin.eras.rest":"数值单位为 YSR。9+ 表示之后所有纪元的总和。","coin.burn.h":"先发优势已被销毁。","coin.burn.cta":"在区块 3,974 中查看","chain.h1":"一条属于自己的链。","chain.lead":"YSKAR 不运行在其他网络之上。它有自己的区块、自己的点对点网络和自己的规则，并用任何人都能核实的工作量来证明每个区块。","chain.how.h":"一个区块，三个步骤。","chain.why.h":"为什么拥有自己的链很重要","chain.y1.h":"规则由它自己决定","chain.y1.p":"手续费、出块时间和升级都在这里决定，由运行 YSKAR 的人决定，而不是由别人的网络决定。","chain.y2.h":"没有什么需要盲目相信","chain.y2.p":"一直到区块 0 的每个区块，任何人都可以用开源软件在普通电脑上重新计算。","chain.y3.h":"变更公开到来","chain.y3.p":"规则变更会连同它开始生效的区块一起写入代码。每个节点都提前知道。修订版 6 交由社区投票表决。","chain.deep.h":"写给好奇的人：它具体如何运作","chain.deep.p":"从这里开始，页面内容偏技术。下面的一切都来自共识代码和链本身。","netp.lead":"这条链此刻正在做什么，读取自公开的 API。这里没有任何人工估算。","bld.h1":"在它之上开发。","bld.lead":"YSKAR 的一切都是开放的：节点、钱包、挖矿程序、区块浏览器和本网站，均采用 MIT 许可证。公开的 API 无需密钥即可访问。","bld.cta":"试用 API","bld.cta2":"GitHub 上的代码","bld.1.h":"阅读一切","bld.1.p":"协议有明确的规范，共识代码短到可以通读，本网站上的每个数字都来自这些代码或链本身。","bld.2.h":"向链查询","bld.2.p":"区块、转账、地址、手续费、矿池和供应量，全部通过普通 HTTP 提供。无需密钥，无需注册，对任何网站开放。","bld.3.h":"改变它","bld.3.p":"提案通过 YSKAR Lab 公开进行，从最初的想法一直到发布。你用自己的钱包登录。","comm.h1":"没有公司。只有人。","comm.lead":"YSKAR 是一个社区项目，属于使用它的人。他们在这里交流、测试和决策。","comm.ch.h":"在哪里找到大家","comm.do.h":"你可以做的事。这些都不需要任何许可。","comm.lab.h":"一项提案如何变成一个发布版本","comm.safe.h":"注意安全","comm.ann":"Bitcointalk","story.h1":"看步骤，不看日期。","story.lead":"YSKAR 从哪里来，今天运行着什么，接下来是什么。这里没有人承诺交付日期：变更在某个区块生效，而不是在日历上的某一天。","story.why.h":"YSKAR 为什么存在","story.why.say":"目标是一种人们可以在日常生活中使用的货币。稳固的基础放在首位。短暂的炒作不在计划之内。","story.why.p":"YSKAR 属于使用它的人。你的 YSR 存放在一个只有你的十二个助记词才能打开的地址上。不必信任任何人：一直到区块 0 的每个区块，任何人都可以核实。新的 YSR 来自挖矿，绝不来自承诺。","story.run.h":"今天已在运行","story.fix.h":"按区块高度确定","story.plan.h":"已计划，没有日期","story.walk":"从区块 0 开始沿着链走一遍","coin.field.alt":"一片代表全部 2100 万枚 YSR 的光点：已挖出的亮着，已销毁的像余烬一样微微发红，其余的是暗的。","coin.field.burned":"已销毁","coin.f0.h":"21,000,000。永远不会更多。","coin.f0.p":"每个光点代表 <span data-field-unit></span> YSR，按它们产生的顺序排列。这就是将会存在的全部。","coin.f1.p":"这是今天已存在的数量，占总量的 <span data-live='mintedPct'></span>。每一枚都出自某个人找到的区块。","coin.f2.p":"早期产生的约 107 万枚 YSR 已被销毁，以抵消先发优势。它们进入了一个任何人都无法花费的地址，永远消失了。","coin.f3.h":"总量的一半最先产生。","coin.f3.p":"最初的 12,000 个区块产生 1050 万枚 YSR：这是未来全部总量的一半。这条链目前位于区块 <span data-live='height'></span>。","coin.f4.h":"之后一次又一次地减半。","coin.f4.p":"每 12,000 个区块，奖励减半一次。最后一枚新的 YSR 出现在区块 443,999。此后矿工只赚取手续费。","coin.noprice.say":"YSR 今天没有价格。它没有在任何地方上市。它拥有的，是一条任何人都能核实的链。","wal.phone.alt":"一部手机依次展示 YSKAR Wallet 的真实界面。","wal.s1.h":"你的余额，一目了然。","wal.s3.h":"一份记录，涵盖一切。","wal.s3.p":"付款、区块奖励和矿池分成都显示在同一个地方。金额精确到小数点后第 8 位。","wal.s5.h":"给地址起个名字。","wal.s5.p":"给地址起一次名字：钱包会在你的付款记录里和发送时显示它。联系人只保存在你的设备上。","pay.alt":"许多小光点闪烁着，汇聚成一个明亮的点并变成一个区块，随后光线从区块射向它付款的每一个地址。","pay.0.h":"所有人同时在猜。","pay.0.p":"此刻整个网络的算力约为 <span data-live='hashrate'></span>：每秒数十亿个数字，全都在寻找同一个区块。","pay.1.h":"有一个数字对上了。","pay.1.p":"大约每十分钟，就有一台机器找到一个可行的数字。这就是一个新区块，然后搜索重新开始。","pay.2.h":"区块向所有出过力的人付款。","pay.2.p":"在矿池中，奖励按每个矿工贡献的工作量分配，并直接在区块内支付。最新的矿池区块一次向 <span id='pay-n'></span> 个地址付了款。","pay.3.h":"无需账户。没有起付门槛。不托管资金。","calcx.a":"我的机器算力为","calcx.b":"我的挖矿方式是","poolsx.last":"最近区块中的占比","poolsx.fee":"手续费","poolsx.seats":"已占名额","poolsx.rate":"上报值","shore.on":"再点亮一盏","shore.off":"把它熄灭","shore.note.on":"第 {k} 盏只在你的屏幕上亮着。等你的节点运行起来，它才算数。","node.check.h":"从区块 0 到今天，无需询问任何人。","comm.vote.say":"2026年10月25日，社区就修订版 6 何时开始进行了投票，最终选定区块 10,000。","comm.vote.cta":"修订版 6 带来了什么","log.k":"截至以下高度的每个区块：","log.cap":"每一行代表自 2026年9月9日（UTC）起的一天，每一道标记代表一个区块及其出现的时刻。暖色标记表示包含转账。点按标记即可打开对应区块。","log.cap.n":"每一行涵盖自 2026年9月9日（UTC）起的 {d} 天，每一道标记代表一个区块。暖色标记表示包含转账。点按标记即可打开对应区块。","log.alt":"这条链的航行日志：自区块 0 起的每个区块都是一道标记，每天一行。","comm.say":"第 {d} 天。{n} 个节点守护着这条链，{m} 位矿工延续着它，{p} 个矿池分担着工作。没有人被任命。他们是自己来的。","road.start.k":"2026年10月25日","road.start":"投票","road.end.k":"区块 10,000","road.end":"修订版 6 开始","road.now":"区块 {h} · 现在","road.left":"还剩 {n} 个区块。按目前的速度，还需要 {eta}。","road.done":"修订版 6 自区块 10,000 起已生效。","road.need":"在那个区块之前，节点需要更新到最新版本。","road.need.done":"仍在使用旧版本的节点已不再跟随这条链。","coin.turn":"翻到另一面","coin.turn.back":"翻回来","coin.back.k":"区块 0","coin.back.d":"2026年9月9日","netp.say":"区块 {h}，{a}找到。{r} 的算力正在寻找下一个。{n} 个节点在关注。","start.jump":"五条路径","start.guides":"每条路径都有分步说明","story.road.h":"迄今为止的链，以及已经确定的事","story.road.p":"沿着这条链有七个标记。已经过去的带有日期。尚未到来的只有区块编号，因为代码只知道这一点。","story.road.live":"查看最新区块","miles.left":"还有 {n} 个区块","forge.hash":"SHA-256，计算两次","forge.target":"不得超过目标值","forge.ok":"有效：已在这台设备上重新计算。","forge.nodes":"{n} 个已报到的节点","forge.nodes.1":"1 个已报到的节点","forge.paid":"{r}，发往 {n} 个地址","forge.paid.1":"{r}，发往一个地址","forge.before":"它之前的 {n} 个区块，按找到时的间隔排列：{m} 分钟","forge.alt":"最新区块头的 136 个字节。Nonce 不断变化，直到哈希低于目标值；随后节点对它进行核实，区块在链的末端就位并支付奖励。","term.note.live":"公开 API 于 {d} 给出的回答。","term.note.snap":"{d} 的回答。API 目前没有响应；页面会自动再次请求。","term.more":"显示全部 {n} 行","term.less":"显示更少的行","term.alt":"向公开 API 发出的一次请求及其回答","agol.sec":"{n} 秒前","agol.sec.1":"1 秒前","agol.min":"{n} 分钟前","agol.min.1":"1 分钟前","agol.hours":"{n} 小时前","agol.hours.1":"1 小时前","agol.days":"{n} 天前","agol.days.1":"1 天前","netp.k":"实时网络","netp.k.snap":"{date} 的网络","netp.say.snap":"当时最新的是区块 {h}。{r} 的算力正在寻找下一个。{n} 个节点在关注。","netp.lead.snap":"这是本页面收到的最后一个状态。公开 API 目前没有响应；页面会自动再次请求。","ex.h1":"每个区块都是公开的。","ex.lead":"查找区块、转账或地址。你的浏览器会重新计算它所显示的每个区块的工作量证明。","ex.q.ph":"区块、哈希或地址","pulse.tip.h":"最近 {n} 小时","pulse.next":"区块 {h} 正在挖掘中。距离上一个区块已过去 {t}。","pulse.around.h":"区块 {h} 前后","pulse.around.n":"这 {k} 小时内有 {n} 个区块","pulse.now":"当前","pulse.by":"发现者：{who}","pulse.alt":"时间线上的区块。每一盏灯是一个区块；两盏灯之间的距离就是它们相隔的时间。","ex.row.tx":"{n} 笔转账","ex.row.tx.1":"1 笔转账","ex.row.tx0":"没有转账","ex.proof.h":"工作量证明","ex.proof.p":"矿工不断转动区块头中的两个计数器，即 nonce 和 extranonce，直到全部 136 个字节的哈希低于目标值。你的浏览器刚刚重复了这一计算。","proof.pick":"选择一个字段，查看其中的内容。","pulse.around.n.1":"这 {k} 小时内唯一的区块","ex.tx.batch":"批量付款","ex.tx.script":"脚本账户支出","ex.txv.status":"状态","ex.txv.waiting":"等待打包进区块","ex.txv.sumPending":"已发送，但尚未进入任何区块。","ex.txv.expected":"预计进入区块 {h}，大约 {min} 分钟后，前提是没有手续费更高的交易到来。","ex.txv.unknownWhen":"在队列中的位置比预测范围更靠后。","ex.addr.waiting":"等待中","ex.addr.older":"加载更早的动态","ex.next.tag":"生成中","ex.next.h":"目前已经确定的内容","ex.next.reward":"奖励","ex.next.pending":"待处理交易","ex.next.empty":"交易池为空，因此该区块目前只包含 Coinbase。","ex.next.some":"待处理的付款会尽可能多地放入这个区块。","ex.next.who":"尚不知道由谁找到它。","ex.fill":"已用 {p}%","ex.fill.of":"{n} / {max} 笔交易","ex.queue.h":"队列","ex.queue.row":"{n} 笔 · 最低 {fee} · 约 {min} 分钟","ex.queue.none":"没有等待中的交易 — 下一个区块会全部打包。","ex.queue.more":"共 {n} 笔交易，分布在 {b} 个区块。","ex.queue.note":"按每字节手续费预计的顺序，假设没有新交易加入。手续费指不带备注的普通转账。","ex.check.h":"在你的浏览器中验证","ex.check.note":"这些检查在这里进行，而不是在服务器上。","ex.check.ser":"序列化","ex.check.hash":"哈希已重新计算","ex.check.pow":"工作量证明","ex.check.link":"链接","ex.check.ok":"有效","ex.check.bad":"无效","ex.check.open":"待定","ex.check.p":"区块头会根据其字段重建、进行双重哈希、与记录的难度比对，并沿着链的链接追溯。这些检查在这里进行，而不是在服务器上。显示哪些区块来自服务器的镜像；镜像会与全节点比对，如有差异会在此显示。区块上的绿点表示：已在此处验证。","ex.f.achieved":"达到","ex.f.time":"出块时间","ex.f.time.s":"距上一个区块","ex.verdict.ok":"已在此处验证 {n} 个区块","ex.verdict.ok.1":"已在此处验证 {n} 个区块","ex.verdict.bad":"有一项检查未通过","ex.verified":"已在此验证","ex.mirror.fork":"镜像在高度 {h} 显示的区块与全节点不同。下面的列表可能位于另一条分支。","ex.mirror.behind":"镜像落后全节点 {n} 个区块。下面缺少最新的区块。","ex.mirror.behind.1":"镜像落后全节点 {n} 个区块。下面缺少最新的区块。","lv.an.apk.akku":"部分设备仍会为了省电而关闭后台应用。如果挖矿自行停止，请将应用的电池使用设置为“不受限制”（设置 → 应用 → YSKAR Wallet → 电池）。","lv.an.apk.dienst":"从 1.0.9 版起，由应用内的独立服务负责计算。离开应用或锁定屏幕后，挖矿仍会继续。挖矿期间，Android 会显示一条带有算力的通知；点击“停止挖矿”即可直接停止。","lv.an.apk.hintergrund":"后台挖矿","lv.an.apk.inst":"安装","lv.an.apk.knopf":"下载最新版本","lv.an.apk.m1":"打开“挖矿”标签页，向下滑到“控制”。","lv.an.apk.m2":"选择模式：Solo 或矿池。在矿池模式下，应用会推荐一个开放的矿池；点击“更换”可查看所有矿池及其矿工数、算力、已找到的区块和手续费。已满的矿池无法选择。","lv.an.apk.m3":"设置“Worker”和“占用率”。Worker 是参与计算的处理器核心；占用率决定它们的负载（25% 到 100%）。","lv.an.apk.m4":"点击“开始挖矿”。如果 Android 询问通知权限，请允许：这样你能看到挖矿正在进行，也可以在通知里直接停止。","lv.an.apk.name":"这款应用在手机上显示为“YSKAR Wallet”。它与不含挖矿功能的新版 YSKAR Wallet 是不同的应用，两者可以同时安装，你的 12 个单词在两者中都能使用。","lv.an.apk.pruefen":"校验下载文件（可选）","lv.an.apk.pruefenText":"每个发布版本还包含一个以 <code>.sha256</code> 结尾的文件，其中是 APK 的校验和。如果你下载文件的校验和与之一致，那么该文件就与我们发布的完全相同。","lv.an.apk.s1":"在手机上打开下载页面，点击文件 <code>yskar-wallet-….apk</code>。","lv.an.apk.s2":"Android 会询问是否允许安装来自此来源（例如你的浏览器）的应用。点击“设置”，并为此来源开启允许。","lv.an.apk.s3":"返回并点击“安装”。Google Play 保护机制可能会显示警告；对于 Play 商店以外的应用，这是正常现象。","lv.an.apk.s4":"打开应用，创建钱包，或用 12 个助记词恢复已有的钱包。","lv.an.apk.start":"开始挖矿","lv.an.apk.text":"Android 应用可以在后台持续挖矿，即使屏幕锁定也不会中断，并通过主屏幕小组件显示你的挖矿状态。由于 Google Play 不允许在设备上挖矿，此版本直接由我们提供。","lv.an.apk.tipp":"我们的建议：全部 Worker、占用率 25%、加入矿池。这样更省电、发热更低，而且在矿池中会更规律地收到小额收益。“校准设备”可以为你的手机找出最合适的 Worker 数量。","lv.an.apk.titel":"支持挖矿的 Android 应用","lv.an.apk.update":"更新应用","lv.an.apk.updateText":"有新版本时，应用会在打开时显示提示。点击“下载”：应用会下载更新，随后 Android 会询问是否安装。你的钱包会保留。也可以在应用的 设置 → 应用 → 更新 中手动检查。","lv.an.apk.w1":"长按主屏幕空白处，选择“小组件”，把“YSKAR Wallet”拖到屏幕上。","lv.an.apk.w2":"挖矿进行时，小组件会显示本次挖矿的收益，以及算力、运行时间和已接受的 Share。点击“停止”可直接在主屏幕上停止挖矿。挖矿停止时，会显示当前区块、全网算力和区块奖励。","lv.an.apk.w3":"“本次挖矿收益”统计的是自启动以来记入你地址的区块奖励和矿池分成；每当找到新区块时，数值才会变化。浅色或深色可在应用的 设置 → 应用 → 小组件 中选择。这种样式的小组件自 1.1.0 版起提供。","lv.an.apk.widget":"主屏幕小组件","lv.an.etikett":"教程","lv.an.ex.p1":"可按区块高度、哈希或地址搜索。","lv.an.ex.p2":"每个区块都会显示是谁找到的：一个名称、一个矿池或一个 Solo 地址。","lv.an.ex.p3":"输入你自己的地址，核对你收到的支付。","lv.an.ex.text":"<a href=\"/explorer\">区块浏览器</a>显示每个区块、每笔转账和每个地址。它在你的浏览器中重新组装每个区块头，计算哈希，并核实工作量证明和链。转账、签名和余额由全节点核实：自己运行一个，你就不必相信任何人。","lv.an.ex.titel":"区块浏览器","lv.an.gr.aus":"矿池如何支付","lv.an.gr.aus1":"区块本身直接支付给所有参与者。矿池运营者从不持有你的资金，也没有最低支付额。","lv.an.gr.aus2":"计入的是最近一段时间的工作量，以 Share 计量。如果你刚刚开始，在第一个区块中得到的份额也就相应较小。","lv.an.gr.gebuehr":"运营者可以收取 0 到 5 % 的手续费。手续费显示在矿池列表中。","lv.an.gr.hinweis":"没有人能向你承诺收益。你多久能收到一次，取决于你的算力、全网算力和运气。","lv.an.gr.p1":"YSKAR 是一条独立的区块链。大约每 10 分钟会找到一个新区块。谁找到它，奖励——目前为 875 YSR——就直接发放到谁的地址上。","lv.an.gr.p2":"为了找到区块，你的设备会逐个尝试数字（双重 SHA-256）。算力越高，机会越大。难度会随全网算力调整。","lv.an.gr.plaetze":"一个区块最多可以向 64 个地址支付，因此一个矿池最多有 64 个名额（收取手续费时为 63 个）。名额只在你挖矿期间有效：新设备先试用 2 分钟，之后需定期提交 share 才能保留。停止挖矿者的名额会重新空出。","lv.an.gr.pool":"<strong>矿池：</strong>许多人一起寻找。矿池找到区块时，奖励按贡献的工作量分配。金额较小，但更有规律。","lv.an.gr.solo":"<strong>Solo：</strong>你独自寻找。如果找到区块，整个奖励都归你。这可能需要很长时间。","lv.an.gr.sp":"Solo 或矿池","lv.an.gr.titel":"挖矿是如何运作的","lv.an.hi.a1":"Android 为了省电而关闭了应用。请将 YSKAR Wallet 的电池使用设置为“不受限制”（设置 → 应用 → YSKAR Wallet → 电池）。","lv.an.hi.a2":"一个矿池最多有 64 个名额。矿工停止挖矿时，名额会立即空出；矿工失去响应时，最多 20 分钟后空出，所以稍后再试可能就行。否则请选择其他矿池，或使用 Solo 挖矿。如果你的地址已经占有一个名额，其他设备仍然可以加入。","lv.an.hi.a3":"节点还没有找到其他节点。请检查你的互联网连接，并确认你在 Windows 防火墙询问时允许了 Node Core。然后稍等片刻。","lv.an.hi.a4":"节点仍在同步。概览显示“In sync”后，挖矿就会开始。","lv.an.hi.a5":"显卡挖矿需要 NVIDIA、AMD 或 Intel 显卡及最新驱动程序。请安装显卡厂商的最新驱动程序，并重新启动 Node Core。每张显卡在挖矿前会进行自检，未通过自检的显卡不会被使用。","lv.an.hi.a6":"请用相同的 12 个助记词、按相同的顺序恢复钱包。不同的助记词对应的是另一个钱包。","lv.an.hi.a7":"有问题请到 <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">Telegram 社区群</a>提问。错误请在 <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a> 上报告。切勿透露你的 12 个助记词：管理员绝不会主动私信你。","lv.an.hi.f1":"手机上的挖矿自行停止","lv.an.hi.f2":"“Pool full”","lv.an.hi.f3":"Node Core：“No peer connected yet”","lv.an.hi.f4":"Node Core：挖矿没有开始","lv.an.hi.f5":"找不到显卡","lv.an.hi.f6":"新设备上没有我的余额","lv.an.hi.f7":"其他问题","lv.an.hi.titel":"遇到问题时","lv.an.mini.hinweis":"提示：在“挖矿”标签页中可以选择 Solo 或矿池。在矿池中你会更频繁地收到较小的金额；Solo 则是较少出块，但每次获得整个区块的奖励。","lv.an.mini.s1":"在 Telegram 中打开 <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> 并启动应用。","lv.an.mini.s2":"点击“创建钱包”。应用会显示 12 个助记词：请按顺序把它们抄写在纸上。","lv.an.mini.s3":"确认其中几个词，并设置 PIN。","lv.an.mini.s4":"打开“挖矿”标签页，点击“开始挖矿”。计算期间请保持应用打开。","lv.an.mini.text":"最快的入门方式。小程序在 Telegram 内运行，无需安装任何东西。","lv.an.mini.titel":"Telegram 小程序","lv.an.nc.e1":"<strong>节点：</strong>数据文件夹、端口和种子节点已预先填好。默认值适合大多数人——直接点击“Continue”即可。","lv.an.nc.e2":"<strong>钱包：</strong>创建一个新钱包并抄写 12 个助记词，或者用你的 12 个助记词迁移已有的钱包。设置一个至少 8 个字符的密码；它会加密这台电脑上的助记词。你也可以稍后再设置钱包。","lv.an.nc.e3":"<strong>启动：</strong>点击“Start node”。","lv.an.nc.einst":"设置","lv.an.nc.erst":"首次启动","lv.an.nc.firewall":"首次启动时，Windows 会询问是否允许 Node Core 访问网络。请允许，否则节点无法找到其他节点。","lv.an.nc.firewallLinux":"Linux 上不会出现这个询问。如果启用了防火墙（例如 ufw），请开放 8646 端口——否则其他节点无法连接到你的节点。你自己的连接无论如何都能正常工作。","lv.an.nc.i1":"下载安装程序并运行。","lv.an.nc.i2":"由于安装程序未签名，Windows 会显示“Windows 已保护你的电脑”。请选择“更多信息”，再点击“仍要运行”。","lv.an.nc.i3":"按照安装程序的提示操作。之后 Node Core 会启动。","lv.an.nc.inst":"在 Windows 上安装","lv.an.nc.l1":"<strong>Ubuntu、Debian、Linux Mint：</strong>下载 <code>.deb</code> 文件并在终端中安装。然后从应用菜单启动“YSKAR Node Core”。","lv.an.nc.l2":"<strong>其他发行版：</strong>下载 AppImage，将其设为可执行并启动。AppImage 需要 FUSE 2（Ubuntu 上为 <code>libfuse2</code> 软件包）。","lv.an.nc.l3":"Linux 版 Node Core 可在带桌面环境的 64 位电脑（x86-64）上运行。不支持树莓派等 ARM 电脑。","lv.an.nc.linux":"在 Linux 上安装","lv.an.nc.m1":"选择目标：Solo 或矿池。在矿池模式下，从列表中选择一个矿池，或在“Your own pool address”下输入地址并进行检查。","lv.an.nc.m2":"“Reward goes to”：你自己的钱包或其他地址。","lv.an.nc.m3":"选择设备：处理器、显卡或两者都用。设置核心数量和每个核心的占用率。","lv.an.nc.m4":"仅限 Solo：如果愿意，可以填写一个名称，它会出现在你找到的区块中。该名称是公开的，并永久保留。","lv.an.nc.m5":"点击“Start mining”。","lv.an.nc.mining":"挖矿","lv.an.nc.poolHinweis":"如果矿池不再接受你，挖矿会停止并告诉你原因。它绝不会悄悄转为 Solo 继续挖矿。","lv.an.nc.port":"我需要开放端口吗？","lv.an.nc.portText":"不需要。不开放端口时，你的节点会自行连接到其他节点。如果你在路由器中转发 8646 端口，其他节点也能连接到你的节点。这对网络有帮助，但是可选的。","lv.an.nc.pruefen":"要确认该文件就是我们发布的文件，请将它的校验和与发布版本中的 <code>.sha256</code> 文件进行比对。在 PowerShell 中：","lv.an.nc.pruefenLinux":"在 Linux 上：","lv.an.nc.s1":"<strong>随 Windows 启动</strong>（Linux 上为“登录时启动”）：你登录时，Node Core 会在不显示窗口的情况下启动。","lv.an.nc.s2":"<strong>关闭后继续运行：</strong>窗口会隐藏到时钟旁的通知区域，节点继续工作。","lv.an.nc.s3":"<strong>启动后恢复挖矿：</strong>节点同步完成后，挖矿会按上次的设置继续。","lv.an.nc.s4":"<strong>更新：</strong>有新版本时，Node Core 会提示你。不会自行安装任何东西。","lv.an.nc.sig":"签名与 YSKAR Lab","lv.an.nc.sigText":"从 1.1.0 版起，钱包中的“签名”可用你的地址对一段文字签名，例如证明某个地址属于你；“验证”可检查他人签名的消息。在 <a href=\"https://lab.yskar.app\">lab.yskar.app</a> 上，“使用钱包登录”会打开 Node Core：它会显示网站、你的地址以及请求的有效期，只有在你用密码确认后才会签名。签名无法转移 YSR。","lv.an.nc.sync":"首次同步","lv.an.nc.syncText":"首次启动时，Node Core 会下载整条区块链并检查每一个区块。这可能需要一些时间；概览会显示进度。只有当节点追上网络的最新状态后，挖矿才会开始。","lv.an.nc.text":"Node Core 是 YSKAR 的 Windows 和 Linux 程序：在一个窗口中集成你自己的节点、钱包和挖矿。它会把区块链下载到你的电脑上，并自行检查每一个区块。","lv.an.nc.titel":"Windows 和 Linux 版 Node Core","lv.an.nc.update":"更新","lv.an.nc.updateText":"下载新的安装程序，退出 Node Core——通知区域中的也要退出——然后运行安装程序。你的钱包和区块链会保留。","lv.an.nc.v1":"Windows 10 或 11（64 位）或 Linux（64 位，x86-64），以及互联网连接","lv.an.nc.v2":"用于存放区块链的磁盘空间。它目前还很小，并随每个区块增长。","lv.an.nc.v3":"使用显卡挖矿：需要一块 NVIDIA、AMD 或 Intel 显卡和最新的驱动程序。没有显卡时，由处理器进行计算。","lv.an.nc.vor":"你需要准备","lv.an.nc.w1":"<strong>发送：</strong>输入收款方和金额，核对后用密码确认。每次转账前都会要求输入密码。","lv.an.nc.w2":"<strong>接收：</strong>显示你的地址或其二维码。","lv.an.nc.w3":"<strong>联系人：</strong>用名称代替地址，只保存在这台电脑上。","lv.an.nc.w4":"<strong>锁定：</strong>钱包在 10 分钟无操作后会自行锁定，Windows 被锁定时也会锁定。你可以在设置中更改这个时间。","lv.an.nc.wallet":"钱包","lv.an.node.s1":"1. 构建","lv.an.node.s2":"2. 启动并连接到网络","lv.an.node.s2Text":"节点会连接到另一个节点（种子节点），加载区块链并逐块检查。如果你在路由器中开放 8646 端口，其他节点就能连接到你的节点；这是可选的。加上 --no-upstream 后，你的节点只把区块传给其他节点，不会传给项目的网页服务器。","lv.an.node.s3":"3. 连接你自己的节点挖矿","lv.an.node.s4":"4. 运行矿池（可选）","lv.an.node.s4Fuss":"--pool-fee 以基点为单位：100 = 1.00 %，最高 500。","lv.an.node.s4Mehr":"矿池需要具备哪些条件，才能让应用和其他矿工连接到它，详见<a href=\"/anleitungen#pool\">运行矿池</a>。","lv.an.node.s4Text":"任何节点都可以成为矿池，无需注册。区块本身会向所有参与者支付；你从不经手他人的资金。","lv.an.node.s5":"5. 在树莓派上作为服务运行","lv.an.node.s5Text":"为了让节点在重启后自动启动，请将它设置为 systemd 服务。现成的文件和说明位于代码仓库的 <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a> 中。","lv.an.node.text":"全节点会下载整条区块链，并亲自检查每一个区块——工作量证明、签名、余额。它需要 Node.js 22.13 或更高版本，在树莓派上也能良好运行。","lv.an.node.titel":"运行全节点","lv.an.node.win":"在 Windows 上，请用 npm.cmd 代替 npm。","lv.an.pc.s1":"1. 安装 Node.js","lv.an.pc.s1Text":"挖矿程序需要 Node.js 20 或更高版本。从 <a href=\"https://nodejs.org\">nodejs.org</a> 下载 LTS 版本并安装。在 Windows 上，安装后请打开一个新的命令行窗口。","lv.an.pc.s2":"2. 获取挖矿程序","lv.an.pc.s2Text":"无需再安装其他任何东西。自检会确认你的电脑能正确计算哈希。","lv.an.pc.s3":"3. 开始挖矿","lv.an.pc.s3Text":"把地址替换成你自己的 YSKAR 地址（以 ysr1 开头）。使用矿池：","lv.an.pc.s4":"4. 显卡（可选）","lv.an.pc.s4Text":"如果有显卡，请加上 <code>--gpu</code>。这需要一个 GPU 程序：NVIDIA 显卡使用 <code>yskar-cuda</code>，AMD 和 Intel 显卡使用 <code>yskar-opencl</code>。挖矿程序会使用第一个找到显卡的程序；加上 <code>--gpu-api opencl</code> 时，即使装有 NVIDIA 显卡也会使用 AMD/Intel 程序。Linux 版两者都附在每个 Node Core 发布版本中（<code>yskar-cuda-…-linux-x86_64</code>、<code>yskar-opencl-…-linux-x86_64</code>）；在 Windows 上，请按照代码库中 <code>node-core/gpu</code> 的说明自行编译。","lv.an.pc.s5":"5. 使用 HiveOS 的矿机","lv.an.pc.s5Text":"使用 HiveOS 的矿机有现成的软件包：本挖矿程序加 GPU 程序，每张 NVIDIA、AMD 或 Intel 显卡一个挖矿进程，不收取费用。它附在每个 Node Core 版本中，文件名为 <code>yskar-hiveos-….tar.gz</code>。如何设置 flight sheet 请见 <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>。","lv.an.pc.solo":"用 Solo 代替矿池：去掉 --mode pool。每次获得整个区块，但出块更少。","lv.an.pc.text":"挖矿程序可在 Windows、macOS 和 Linux 上运行。它只需要一个地址——不需要私钥、不需要钱包、无需注册。你可以放心地在任何电脑上运行它。","lv.an.pc.titel":"电脑挖矿程序","lv.an.pool.beitritt":"矿工如何加入","lv.an.pool.beitrittText":"在应用中选择“矿池”，并在“自定义地址”下输入你的矿池地址；在 Node Core 中则在“Your own pool address”下输入。使用电脑挖矿程序：","lv.an.pool.caddy":"Caddy 的配置。把名称替换成你自己的；它必须事先指向你的机器。","lv.an.pool.g1":"<strong>名称：</strong>3 到 32 个简单字符。它会写入你矿池的每一个区块，并永久保留在那里。","lv.an.pool.g2":"<strong>手续费：</strong>0 到 5 %。在命令中，<code>--pool-fee</code> 以基点为单位：100 = 1 %。收取手续费时，必须指定接收手续费的地址。","lv.an.pool.g3":"<strong>名额：</strong>最多 64 个地址；收取手续费时为 63 个——其中一个收款方是你自己。","lv.an.pool.g4":"<strong>不经手他人的资金：</strong>区块直接支付给所有人。你从不持有矿工的资金。","lv.an.pool.h1":"打开“Run a pool”，设置名称、手续费和名额数量，然后开启。","lv.an.pool.h2":"在挖矿页面选择“Pool”。你自己的矿池排在最前面。","lv.an.pool.h3":"如需接入更多电脑，请开启“Devices in your home network”。它们通过 <code>http://&lt;这台电脑的地址&gt;:8645</code> 连接。","lv.an.pool.heim":"在家庭网络中使用 Node Core","lv.an.pool.heimText":"Node Core 中的矿池只响应你自己的电脑和你自己的网络。这样无法从互联网访问它。","lv.an.pool.k1":"谁和你一起挖矿","lv.an.pool.k2":"你需要准备","lv.an.pool.liste":"进入矿池列表","lv.an.pool.listeText":"应用和 Node Core 会显示一份经过维护的矿池列表。要被收录，你的矿池必须可以通过 HTTPS 访问，并响应 <code>/api/v2/pool</code>。请在 <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a> 上提出申请。该列表既不是审核，也不是推荐：矿工数、算力和手续费由矿池自行报告。","lv.an.pool.n1":"<strong>一个持续运行的节点。</strong>最好是在树莓派或服务器上运行的命令行节点，参见<a href=\"/anleitungen#fullnode\">运行全节点</a>。","lv.an.pool.n2":"<strong>一个名称</strong>，别人可以通过它访问节点：你自己的域名，或免费的 DynDNS 名称。","lv.an.pool.n3":"<strong>带有效证书的 HTTPS。</strong>Telegram 和浏览器不会加载任何未加密的内容。没有 HTTPS，任何手机都无法连接到你的矿池。","lv.an.pool.n4":"<strong>前面放一台 Web 服务器</strong>，由它获取证书并把请求转发给节点，例如 Caddy。","lv.an.pool.n5":"<strong>开放 443 端口。</strong>对于家里的节点，这意味着要在路由器中设置端口转发。","lv.an.pool.netz":"面向应用、小程序和来自互联网的矿工","lv.an.pool.netzText":"你需要：","lv.an.pool.o1":"<strong>在家里：</strong>没有额外费用。但你的 IP 地址会被公开，你需要设置端口转发，负载也由你的网络连接承担。","lv.an.pool.o2":"<strong>租用服务器：</strong>不涉及你家里的 IP 地址，服务器上也不保存任何私钥——只有接收手续费的地址。请先阅读服务商的条款：许多服务商禁止挖矿或任何与之相关的用途。请取得书面许可。","lv.an.pool.ort":"放在家里还是租用的服务器上？","lv.an.pool.r1a":"你和你家庭网络中的设备","lv.an.pool.r1b":"开启了“Run a pool”的 Node Core","lv.an.pool.r2a":"来自互联网的电脑挖矿程序","lv.an.pool.r2b":"一个持续运行并且可以从外部访问的节点","lv.an.pool.r3a":"应用和小程序","lv.an.pool.r3b":"另外需要 HTTPS：一个名称（域名或 DynDNS）和一份证书","lv.an.pool.regeln":"每个矿池都适用的规则","lv.an.pool.start":"以矿池方式启动节点。它只在本机上监听；Web 服务器位于它前面。","lv.an.pool.test":"从外部检查。如果响应中包含你的矿池名称和名额数量，说明矿池可以访问。","lv.an.pool.text":"YSKAR 的矿池不是带账户的服务。它是一个会分配自己区块奖励的节点。任何人都可以运行，无需注册。你需要什么，取决于谁要和你一起挖矿。","lv.an.pool.titel":"运行矿池","lv.an.si.p1":"<strong>你的 12 个助记词就是你的钱包。</strong>切勿在任何网站上输入，切勿发送给任何人。YSKAR 的任何人都不会向你索要助记词。","lv.an.si.p2":"<strong>只从 yskar.app 和 GitHub 上的 YSKAR 项目下载。</strong>如果想确认无误，请比对校验和。","lv.an.si.p3":"<strong>保持软件为最新版本。</strong>遇到已公布的规则变更时，过时的节点要么停在那个区块上，要么继续运行却不检查新规则——两者都说明应及时更新。","lv.an.si.p4":"<strong>运行节点时：</strong>其他节点能看到你的 IP 地址，任何点对点网络都是如此。你不需要端口转发。如果不想让别人看到你的地址，请使用 VPN。","lv.an.si.p5":"<strong>Node Core：</strong>钱包和界面只能从你自己的电脑访问。","lv.an.si.titel":"安全","lv.an.text":"所有内容都分步讲解：在手机和电脑上挖矿、你的钱包、你自己的节点和你自己的矿池。","lv.an.titel":"一步一步","lv.an.tocLabel":"本页内容","lv.an.ue.k1":"方式","lv.an.ue.k2":"适合","lv.an.ue.k3":"你需要","lv.an.ue.r1a":"Telegram 小程序","lv.an.ue.r1b":"想马上试一试","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"Android 应用","lv.an.ue.r2b":"在手机后台挖矿","lv.an.ue.r2c":"一部 Android 手机","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"在电脑上运行自己的节点，带钱包和挖矿，也可使用显卡","lv.an.ue.r3c":"Windows 10/11 或 Linux（64 位）","lv.an.ue.r4a":"电脑挖矿程序","lv.an.ue.r4b":"通过命令行挖矿","lv.an.ue.r4c":"装有 Node.js 的 Windows、macOS 或 Linux","lv.an.ue.r5a":"全节点","lv.an.ue.r5b":"在树莓派或服务器上运行节点或矿池","lv.an.ue.r5c":"装有 Node.js 22.13 或更高版本的 Linux、Windows 或 macOS","lv.an.ue.text":"参与的方式有五种。它们都使用同一个钱包：凭你的 12 个助记词，在哪里都能访问同一份余额。","lv.an.ue.titel":"哪种方式适合你？","lv.an.w.empfangen":"接收","lv.an.w.empfangenText":"显示你的地址或其二维码。你可以在二维码中加入金额和备注；这样发送方只需确认即可。你的地址可以告诉任何人——你的 12 个助记词不能告诉任何人。","lv.an.w.kontakte":"联系人和记录","lv.an.w.kontakteText":"联系人为地址起一个名称；它们只保存在你的设备上。记录会显示每一笔付款；一天的挖矿收益合并为一行，可以展开查看到单个区块。","lv.an.w.s1":"收款方：粘贴地址、扫描二维码或选择联系人。YSKAR 地址以 ysr1 开头。","lv.an.w.s2":"金额；如果愿意，还可以添加最多 32 字节的备注——即 32 个英文字母，中文约 10 个字。备注会公开保存在区块链中。","lv.an.w.s3":"手续费：应用会给出建议。网络不拥堵时，最低手续费即可进入下一个区块。","lv.an.w.s4":"核对：应用会显示完整地址，并告诉你是否曾向它发送过。用 PIN 或指纹确认。","lv.an.w.senden":"发送","lv.an.w.warn":"已发送的付款无法撤回。确认之前，请核对完整的地址。","lv.an.wallet.p1":"按正确顺序把助记词抄写在纸上。不要截图，不要存到云端。","lv.an.wallet.p2":"妥善保管这张纸。即使丢了手机，助记词也能恢复一切。","lv.an.wallet.p3":"PIN 只保护本设备上的应用，它无法替代助记词。","lv.an.wallet.p4":"要迁移到新设备，请选择“我已有 12 个助记词”并输入它们。","lv.an.wallet.text":"你的钱包由 12 个助记词在你的设备上生成。这些助记词就是你的私钥：谁拥有它们，谁就能动用资产——在任何设备、任何 YSKAR 应用中。","lv.an.wallet.titel":"你的钱包","lv.fuss.datenschutz":"隐私政策","lv.fuss.impressum":"网站信息","lv.hood.f2.k":"难度","lv.nc.appimage":"适用于其他 Linux 发行版的 AppImage","lv.nc.bildNotiz":"示例界面，数字仅为示例。","lv.nc.knopfLinux":"下载 Linux 版（.deb）","lv.nc.knopfWin":"下载 Windows 版","lv.nc.mehr":"校验和与版本说明","lv.nc.system":"Windows 10 或 11（64 位）","lv.nc.systemLinux":"Linux 64 位 · Ubuntu、Debian、Mint","lv.pr.block.alt":"136 字节的区块头及其十个字段","lv.pr.block.merkle":"对区块中所有交易计算出的一个哈希。任何一笔转账中改动一个字节，它都会改变。","lv.pr.block.nonce":"矿工不断变换的数字。前 128 字节在一个任务中保持不变，因此每次尝试只需要两步 SHA-256 压缩。","lv.pr.block.prev":"前一个区块的哈希。它把链连接起来：修改一个旧区块，会改变其后的每一个哈希。","lv.pr.block.state":"对本区块之后所有账户（余额和 nonce）计算出的一个哈希。每个节点都会自行计算并进行比较。","lv.pr.block.text":"每个区块都以正好 136 字节开头。它的哈希是对这些字节进行双重 SHA-256 计算的结果，并且不得超过难度所设定的目标值。","lv.pr.block.titel":"区块头的结构","lv.pr.db.ablauf":"过期","lv.pr.db.ablaufWert":"可选，按区块高度","lv.pr.db.adresse":"地址","lv.pr.db.adresseWert":"ysr1…，42 个字符；V6 起的共享账户：ysr1p…，63 个字符（bech32m）","lv.pr.db.blockzeitWert":"600 秒（目标值）","lv.pr.db.diffWert":"LWMA，基于 45 个区块，每个区块调整","lv.pr.db.einheit":"最小单位","lv.pr.db.gebuehr":"手续费归属","lv.pr.db.gebuehrWert":"该区块的矿工","lv.pr.db.kette":"区块链","lv.pr.db.knoten":"全节点","lv.pr.db.knotenWert":"每个都保存并检查整条链","lv.pr.db.konsens":"共识","lv.pr.db.konsensWert":"工作量证明，SHA-256d","lv.pr.db.memo":"备注","lv.pr.db.memoWert":"最多 32 字节","lv.pr.db.minGeb":"最低手续费（共识）","lv.pr.db.minGebWert":"每字节 1 个单位","lv.pr.db.modell":"模型","lv.pr.db.modellWert":"带余额和 nonce 的账户","lv.pr.db.muenze":"币","lv.pr.db.name":"名称 · 代码","lv.pr.db.netz":"网络","lv.pr.db.notfall":"紧急规则","lv.pr.db.notfallWert":"30 分钟未出块后降低难度","lv.pr.db.nullkonto":"销毁地址","lv.pr.db.pfad":"密钥派生","lv.pr.db.pool":"矿池","lv.pr.db.poolWert":"由区块支付，手续费 0–5 %","lv.pr.db.relay":"转发的最低手续费","lv.pr.db.relayWert":"每字节 10 个单位","lv.pr.db.sig":"签名","lv.pr.db.staub":"最小发送金额","lv.pr.db.staubWert":"100 个单位","lv.pr.db.transfer":"转账大小","lv.pr.db.transferWert":"168 到 200 字节","lv.pr.db.tx":"每个区块的交易数","lv.pr.db.txWert":"最多 2,000 笔","lv.pr.db.vorab":"预挖 · 预先分配","lv.pr.db.vorabWert":"无","lv.pr.db.wahl":"链的选择","lv.pr.db.wahlWert":"累计工作量最多的链","lv.pr.db.wallet":"钱包与账户","lv.pr.db.worte":"助记词","lv.pr.db.worteWert":"BIP39，12 或 24 个词","lv.pr.etikett":"协议详解","lv.pr.gen.belohnung":"奖励","lv.pr.gen.belohnungWert":"875 YSR，不可花费","lv.pr.gen.text":"链上的第一个区块。它的 coinbase 携带一条简短的消息，其奖励发往一个任何人都无法花费的地址。","lv.pr.gen.titel":"区块 0","lv.pr.gen.zeit":"时间戳","lv.pr.pruefen":"直接在你的浏览器中亲自验证区块 0 或最新区块。","lv.pr.text":"以下所有内容都固定在共识代码中，对每个节点都一样。没有任何内容依赖于某台服务器、某家公司或某项设置。","lv.pr.titel1":"YSKAR 和 YSR，","lv.pr.titel2":"逐字节解析。","lv.pr.tx.alt":"转账的字段","lv.pr.tx.p1":"签名还涵盖链 ID，因此为 YSKAR 签名的转账在任何其他网络上都无效。","lv.pr.tx.p2":"nonce 记录一个账户已发送的转账数。同一笔转账永远不会被执行两次。","lv.pr.tx.p3":"可选的过期高度可以让转账在届时仍未被打包时失效。","lv.pr.tx.text":"转账把 YSR 从一个账户转移到另一个账户。它的大小为 168 字节，外加可选的备注。","lv.pr.tx.titel":"转账的结构","lv.recht.nurDeutsch":"根据德国法律要求，本页面以德语提供。","lv.supply.aera.fuss":"奖励以完整的基本单位（0.00000001 YSR）计算，因此每次减半都会舍去余数：最终总共将发行 20,999,999.99832 YSR，略低于最大值。","lv.supply.aera.k1":"纪元","lv.supply.aera.k2":"区块","lv.supply.aera.k3":"每个区块的奖励","lv.supply.aera.k4":"本纪元发行量","lv.supply.aera.k5":"纪元结束后总量","lv.supply.aera.text":"一个纪元持续 12,000 个区块，约 83 天。每个纪元的奖励是前一个纪元的一半。从区块 444,000 起不再产生新的 YSR，矿工只获得手续费。","lv.supply.aera.titel":"各纪元的发行量","lv.wallet.warnung":"<strong>谁拥有 12 个助记词，谁就拥有资产。</strong>切勿透露给任何人。YSKAR 的任何人都绝不会向你索要助记词。","lv.wpseite.drucken":"打印 / 保存为 PDF","lv.wpseite.toc":"目录","lv.wpseite.untertitel":"一条人人都能挖矿、人人都能验证的工作量证明区块链。","lv.zahlen.blockzeit":"出块时间","lv.wpseite.nurDeEn":"白皮书目前提供英文版和德文版。","unit.min":"{n} 分钟","unit.hours":"{n} 小时","unit.days":"{n} 天","ago.sec":"{n} 秒前","ago.min":"{n} 分钟前","ago.hours":"{n} 小时前","ago.days":"{n} 天前","eta.around":"大约 {d} 后，{date} 前后","v6.active":"自区块 10,000 起生效","v6.pending":"还剩 {n} 个区块","mode.live":"来自链上的实时数据","mode.snapshot":"{date} 的状态","mode.history":"截至区块 {h} 的历史","mode.liveShort":"已发布","mode.snapshotShort":"最后已知的状态","dur.years":"{n} 年","dur.years.big":"{n}年","dur.days":"{n} 天","dur.hours":"{n} 小时","dur.min":"{n} 分钟","dur.sec":"{n} 秒","dur.sec.1":"1 秒","rm.run.p":"已发布并在使用中。每一项都通向你可以核实它的地方。","rm.run.1.h":"主网","rm.run.1.p":"自 2026年9月9日起的区块。这条链目前位于区块","rm.run.1.l":"实时网络","rm.run.2.h":"共识修订版 2 至 5","rm.run.2.p":"自区块 2,000、4,000、6,000 和 7,000 起生效。","rm.run.2.l":"每个修订版改了什么","rm.run.3.p":"适用于 Windows 和 Linux 的全节点、钱包、CPU 和 GPU 挖矿以及矿池运营。","rm.run.3.l":"下载","rm.run.4.p":"安卓钱包：发送、接收、签名。已为修订版 6 做好准备。","rm.run.4.l":"关于钱包","rm.run.5.h":"三个公开矿池","rm.run.5.p":"YSKAR MAIN、Gozero 和 ODW.Serv。矿池软件是开源的，任何人都可以运行一个。","rm.run.5.l":"实时矿池","rm.run.6.h":"区块浏览器和公开 API","rm.run.6.p":"每个区块、每笔转账和每个地址，可在浏览器中查看，也可通过 HTTP 获取。","rm.run.6.l":"打开区块浏览器","rm.run.7.p":"提案、讨论和进展全部公开。你用自己的钱包登录。","rm.fix.p":"这些变更已写入共识代码。它们在某个区块生效，而不是在某个日期：那个区块何时到来，取决于区块被找到的速度。","rm.fix.blocks":"个区块","rm.fix.1.at":"区块 10,000","rm.fix.1.h":"修订版 6","rm.fix.1.p":"最多 16 个密钥的共享账户、时间锁和哈希锁、一次最多向 1,000 个收款方的批量转账，以及每个区块可容纳 5,000 笔交易的空间。这是一次硬分叉，经 2026年10月25日的社区投票确定。在那个区块之前，节点必须运行最新版本。","rm.fix.1.l":"区块 10,000 会有哪些变化","rm.fix.2.at":"区块 12,000","rm.fix.2.h":"第一次减半","rm.fix.2.p":"区块奖励从 875 YSR 降至 437.5 YSR。此后每 12,000 个区块再减半一次。","rm.fix.2.l":"完整的时间表","rm.fix.after":"最后一枚新的 YSR 在区块 443,999 产生。此后矿工只赚取手续费。","rm.plan.p":"这是打算，而不是承诺。这里的任何一项都没有日期，顺序也可能改变。","rm.plan.1.h":"兑换与即时支付","rm.plan.1.p":"修订版 6 为这条链带来基础构件：哈希锁和时间锁。利用它们实现兑换和实时支付的钱包功能会在之后推出。","rm.plan.2.h":"面向矿机的 Stratum","rm.plan.2.p":"目前矿工和矿池使用 YSKAR 自己的 HTTP 协议通信。Stratum 计划在网络规模扩大后推出。","rm.plan.3.h":"挖矿奖励发往共享账户","rm.plan.3.p":"修订版 6 无法把区块奖励支付给共享账户。规范把这一点留给了修订版 7。","rm.plan.4.h":"连接你自己节点的钱包","rm.plan.4.p":"目前 YSKAR Wallet 从公开服务器读取余额。计划：让它指向你自己运行的全节点。","rm.plan.5.h":"YSKAR Wallet 上架 Play 商店","rm.plan.5.p":"目前钱包是 GitHub Releases 上的一个 APK。","rm.plan.6.h":"公开测试网与社区决策","rm.plan.6.p":"YSKAR Lab 的下一阶段：在变更进入主网之前先行试用，并共同做出决定。","rm.plan.7.h":"交易所上市","rm.plan.7.p":"正在筹备中，没有日期，也没有名称。今天 YSR 没有价格，也没有市场，任何人都不应抱着这种情况会改变的期待去挖矿。","rm.how.p":"提案在 YSKAR Lab 上公开撰写、讨论和跟踪。对共识规则的更改需要一份规范，并且只会在每个节点都提前知道的区块高度进入主网。","com.ch.p":"公告会最先发布在 Telegram 频道。其余的渠道用于提问和讨论。","com.ch.1":"发布版本和新闻。","com.ch.2":"与其他矿工和用户提问、讨论。","com.ch.3":"来自 @yskar_official 的简短动态。","com.ch.4":"公告帖。","com.ch.5":"源代码、发布版本和问题反馈。","com.ch.6":"提案，从最初的想法到发布。","com.do.1.h":"运行全节点","com.do.1.p":"每一个亲自核实区块的节点，都让网络更少依赖任何一台服务器。","com.do.2.h":"挖矿，单独挖或加入矿池","com.do.2.p":"算力分散在众多矿工和多个矿池之间，这条链就更难被操纵。","com.do.3.h":"运行矿池","com.do.3.p":"矿池软件是代码仓库的一部分，直接在区块内向矿工付款。多一个独立的矿池，算力就更分散一些。","com.do.4.h":"测试并反馈","com.do.4.p":"试用一个版本，并为出问题的地方提交一个 issue。说明你看到了什么，以及如何重现。","com.do.5.h":"提议并讨论","com.do.5.p":"把想法带到 YSKAR Lab，或者在评论中完善别人的想法。","com.lab.p":"每项提案都经过同样的六个阶段，所有人都能看到它进行到哪一步。","com.lab.s1":"想法","com.lab.s1.d":"分享你的想法。","com.lab.s2":"讨论","com.lab.s2.d":"在评论中一起完善它。","com.lab.s3":"草案","com.lab.s3.d":"文字、设计、规范或代码。","com.lab.s4":"计划中","com.lab.s4.d":"已排入即将到来的某个版本，并附有理由。","com.lab.s5":"测试网上","com.lab.s5.d":"在它进入主网之前先试用。","com.lab.s6":"已发布","com.lab.s6.d":"已发布，并附有链接。","com.lab.k1":"提案的前三个阶段由作者推进。","com.lab.k2":"从“计划中”开始，阶段由团队确定，并始终附有理由。","com.lab.open":"打开 YSKAR Lab","com.safe.1.h":"你的 12 个助记词由你自己保管","com.safe.1.p":"YSKAR 的任何人都不会向你索要你的 12 个助记词、PIN 码或钱包文件。索要这些的人是想拿走你的币。","com.safe.2.h":"从源头下载","com.safe.2.p":"请从本网站链接的 GitHub 发布页获取软件，并在安装前核对钱包的证书指纹。","com.safe.3.h":"没有承诺","com.safe.3.p":"YSR 今天没有价格，也没有市场，没有在任何交易所上市。这里没有任何内容承诺这种情况会改变。","com.channel":"Telegram 频道","com.chat":"社区群聊","wallet.dl":"下载 APK","wallet.meta":"版本 2.0.0，适用于 Android 7 或更高版本。以 MIT 许可证开源。界面语言为英语和德语。","wallet.feat.p":"没有广告，没有追踪，也不需要在任何地方注册账户。这个应用只与 YSKAR 网络通信，不与其他任何对象通信。","wallet.f1.h":"你的私钥由你自己保管","wallet.f1.p":"钱包在你的手机上创建。12 个恢复助记词可以在任何设备上恢复它。它们用你的 PIN 码加密后保存在 Android 的受保护存储中，绝不会进入云备份。","wallet.f2.h":"发送要有意为之","wallet.f2.p":"输入地址、选择联系人或扫描二维码。发送前会再次显示收款方、金额和网络手续费，然后用 PIN 码或指纹确认。转账无法撤回。","wallet.f3.h":"收款","wallet.f3.p":"出示你的二维码，或者复制并分享你的地址。任何人都可以看到它：只知道地址并不能取走任何资金。","wallet.f5.h":"签名与登录","wallet.f5.p":"用一条签名消息证明某个地址属于你，并核实别人的签名。用二维码登录 YSKAR Lab。签名无法转移 YSR。","wallet.f6.h":"层层防护","wallet.f6.p":"PIN 码和指纹，在你选定的时间后自动锁定，显示 12 个助记词时禁止截屏，并使用应用自带的键盘，因此你的输入不会经过手机的键盘应用。","wallet.inst.h":"四步完成安装","wallet.inst.p":"钱包以 APK 的形式通过 GitHub 发布页分发。更新会覆盖安装在旧版本之上，你的钱包仍保留在设备上。","wallet.inst.1":"在你的安卓手机上打开<a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>最新版本</a>，下载文件 <code>yskar-wallet-…apk</code>。","wallet.inst.2":"打开文件。当 Android 询问时，允许从此来源安装。","wallet.inst.3":"点按“Create wallet”，并把 12 个助记词按顺序写在纸上。","wallet.inst.4":"设置一个 PIN 码。如果要迁移已有的钱包，请改为输入它的 12 个助记词。","wallet.verify.h":"核实文件是否为正版","wallet.verify.p":"每个版本都用同一个密钥签名。这是其证书的 SHA-256 指纹。如果你下载的文件指纹不同，请不要安装。","wallet.oth.h":"存放 YSR 的其他地方","wallet.oth.p":"每个 YSKAR 应用都使用同样的 12 个助记词。凭借它们，你在任何地方看到的都是同一份余额。","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android。发送、接收、签名。不挖矿。","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows 和 Linux。一个内置在你自己全节点中的钱包，支持挖矿和消息签名。<a href='/mining#setup'>获取 Node Core</a>","wallet.oth.3.h":"支持挖矿的 Android 应用","wallet.oth.3.p":"在手机上使用钱包和挖矿，带有主屏幕小组件和通知。","wallet.oth.4.h":"Telegram 小程序","wallet.oth.4.p":"最简单的入门方式，无需安装任何东西。所有权取决于你的 12 个助记词，而不是你的 Telegram 账户。","wallet.st.h":"钱包的现状","wallet.st.1.h":"仅限 Android","wallet.st.1.p":"钱包是来自 GitHub 的一个 APK。它不在任何应用商店中，也没有 iOS 应用。","wallet.st.2.h":"已为修订版 6 做好准备","wallet.st.2.p":"版本 2.0.0 支持新的转账格式，并在区块 10,000 切换到该格式。更早的版本仍然可以接收 YSR，但在那个区块之后无法发送。","wallet.st.3.h":"计划：上架应用商店","wallet.st.3.p":"计划通过 Google Play 发布。目前没有日期。","wallet.st.4.h":"计划：连接你自己的节点","wallet.st.4.p":"目前钱包从项目的主节点读取数据。计划支持连接你自己运行的节点，这样任何人都不必在余额问题上只听项目的一面之词。","mining.ways.p":"每种方式都是免费的，并且使用同一个钱包：凭借你的 12 个助记词，你在任何地方都能使用同一批 YSR。","mining.tab.pc":"电脑","mining.tab.phone":"手机","mining.tab.cli":"命令行","mining.tab.rig":"矿机","mining.pc.h":"Windows 和 Linux 版 Node Core","mining.pc.p":"全节点、钱包和挖矿程序，集于一个程序。Node Core 亲自核实每个区块，并用你的处理器以及 NVIDIA、AMD 和 Intel 的显卡挖矿。版本 1.1.0，适用于 Windows 10 和 11 以及 64 位 Linux。","mining.pc.s1":"下载安装程序并运行。","mining.pc.s2":"创建一个钱包并记下 12 个助记词，或者用助记词把你的钱包迁移过来。","mining.pc.s3":"在 Mining 中选择 solo 或矿池，选定处理器或显卡，然后开始。","mining.pc.win":"下载 Windows 版","mining.pc.deb":"下载 Linux 版（.deb）","mining.pc.more":"另外还提供：适用于其他 Linux 发行版的 <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a>，以及<a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>附带校验和的发布说明</a>。","mining.pc.note":"<strong>Windows 安装程序没有签名。</strong>因此 Windows 会询问一次：选择“更多信息”，然后选择“仍要运行”。如果想确认文件就是发布的那一个，请把校验和与发布说明进行比对。","mining.pc.imgcap":"Node Core 概览。图中的数字仅为示例。","mining.phone.h":"在手机上","mining.phone.p":"了解 YSKAR 最简单的方式。手机贡献的算力很少，只有在矿池中才能找到区块。正式的挖矿在电脑和矿机上进行。","mining.phone.s1":"从 GitHub 安装安卓应用，或者在 Telegram 中打开 Mini App。","mining.phone.s2":"创建一个钱包，并把 12 个助记词写在纸上。","mining.phone.s3":"选择一个矿池，开始挖矿。","mining.phone.apk":"支持挖矿的 Android 应用","mining.phone.tg":"Telegram 中的 Mini App","mining.phone.f1":"Android 应用","mining.phone.f1.v":"在后台持续挖矿，锁屏时也不停，并在主屏幕小组件中显示状态。以 APK 形式分发，因为应用商店不允许在设备上挖矿。","mining.phone.f2":"Mini App","mining.phone.f2.v":"无需安装。只要 Telegram 开着，它就在其中运行。你的币取决于你的 12 个助记词，而不是你的 Telegram 账户。","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"钱包应用不挖矿。它是为发送、接收和签名而设计的。","mining.cli.h":"命令行挖矿程序","mining.cli.p":"适用于 Windows、macOS 和 Linux。挖矿程序只需要一个地址：不需要私钥，不需要钱包，也不需要注册。你可以在一台不由你掌控的电脑上运行它。","mining.cli.f1":"前提条件","mining.cli.f1.v":"Node.js 20 或更高版本，无需安装其他任何东西","mining.cli.f2":"显卡","mining.cli.f2.v":"加上 <code>--gpu</code>。NVIDIA 使用 <code>yskar-cuda</code>，AMD 和 Intel 使用 <code>yskar-opencl</code>","mining.cli.f3":"Solo","mining.cli.f3.v":"连接你自己的全节点挖矿，并去掉 <code>--mode pool</code>","mining.cli.link":"挖矿程序的完整教程","mining.cli.c1":"获取挖矿程序并测试这台电脑","mining.cli.c2":"在公开矿池中挖矿","mining.cli.c3":"或者 solo，连接你自己的节点","mining.cli.addr":"把 <code>ysr1...</code> 换成你自己的地址。奖励会直接发到这个地址。","mining.rig.h":"使用 HiveOS 的矿机","mining.rig.p":"为 HiveOS 准备的现成软件包：命令行挖矿程序加上 GPU 程序，每块显卡一个挖矿进程。","mining.rig.dl":"下载软件包 1.1.0","mining.rig.doc":"Flight sheet 与设置","mining.rig.f1":"显卡","mining.rig.f1.v":"NVIDIA（CUDA）、AMD 和 Intel（OpenCL）","mining.rig.f2":"手续费","mining.rig.f2.v":"挖矿程序本身不收取。各矿池收取自己的手续费","mining.rig.f3":"设置","mining.rig.f3.v":"你的地址和矿池填在 flight sheet 中。教程会说明每一个字段","mining.return":"<strong>没有人能向你承诺收益。</strong>你多久能收到一次，取决于你的算力、整个网络的算力以及运气。YSR 没有市场价格。","pools.p1":"Solo 时，你独自寻找，找到区块后独得全部奖励。在矿池中，许多人一起寻找，奖励按每个人贡献的工作量分配。","pools.p2":"YSKAR 矿池不是带账户的服务。它是一个节点，其区块直接在区块内向每位矿工付款。运营者从不持有别人的币，也没有起付门槛。","pools.reported":"上报 {r}","pools.c5":"最近 {n} 个中","pools.full":"已满","pools.cap":"矿工数、名额和算力均为各矿池自行上报。最近 {n} 个区块中的占比则根据链上数据统计。","pools.f1":"结算方式","pools.f1.v":"按最近一段时间的份额计算（PPLNS）。如果你刚刚开始，你在第一个区块中的份额会很小。","pools.f2":"名额","pools.f2.v":"一个区块最多可以向 64 个地址付款，因此一个矿池有 63 个名额，外加运营者的手续费。从修订版 6 起为 254 个。","pools.f3":"手续费","pools.f3.v":"由运营者设定，在 0 到 5 % 之间。","pools.f4":"你自己的矿池","pools.f4.v":"任何节点都可以成为矿池，无需注册。<a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>如何运行矿池</a>","calc.p":"输入你的算力。估算使用的是链上最新区块中的工作量，而不是矿池自行上报的数字。Node Core 和挖矿程序在运行时会显示你的算力。","calc.unit":"单位","calc.mode":"挖矿方式","calc.pool":"矿池","calc.solo":"Solo","calc.which":"矿池","calc.day":"平均每天","calc.week":"每 7 天","calc.month":"每 30 天","calc.share":"你占全网的份额","calc.d.every":"平均每隔多久一个区块","calc.d.chance":"24 小时内至少找到一个区块的概率","calc.d.block":"每找到一个区块","calc.d.poolEvery":"矿池大约每隔多久找到一个区块","calc.d.part":"你在每个矿池区块中的份额","calc.d.fee":"矿池手续费，已扣除","calc.d.poolShare":"矿池在最近 {n} 个区块中的占比","calc.d.net":"根据最近 {n} 个区块得出的全网算力","calc.enter":"请输入大于 0 的算力。","calc.note":"这是估算，不是承诺。区块的发现带有偶然性，难度则跟随整个网络变化。未计入手续费。","calc.halving":"区块 {b} 的减半大约还有 {d} 天。7 天和 30 天的数字已经把减半后的奖励按一半计入。","calc.halving.1":"区块 {b} 的减半大约还有 1 天。7 天和 30 天的数字已经把减半后的奖励按一半计入。","calc.every.min":"{n} 分钟","calc.every.min.1":"1 分钟","calc.every.hours":"{n} 小时","calc.every.days":"{n} 天","calc.every.years":"{n} 年","net.hashrate":"全网算力","net.difficulty":"难度","net.now":"此刻","net.height":"区块高度","net.fromChain":"最近 24 个区块的工作量除以它们的用时","net.everyBlock":"每个区块重新计算一次","net.blocktime":"出块时间，最近 50 个区块","net.target600":"目标：600 秒","net.mempool":"等待中的转账","net.fromNode":"位于主节点","net.miners":"活跃矿工","net.sessions":"挖矿会话","net.nodes":"已报到的节点","net.reported":"自行上报，无法核实","net.next.v6":"修订版 6 在区块 10,000 启用","net.next.halving":"第一次减半在区块 12,000","net.hist.h":"从区块中读取的历史","net.hist.p":"链上的每个区块，按 UTC 日期汇总。历史数据完整至区块 <span data-live='snapTip'></span>；上方的数字为实时读取。","net.range":"时间范围","net.range.all":"自区块 0 起","net.range.30":"30 天","net.range.7":"7 天","net.c.hash":"每日算力","net.c.hash.capLog":"当日区块的工作量除以它们的用时。对数刻度：每条线是下面一条的十倍。","net.c.hash.capLin":"当日区块的工作量除以它们的用时。","net.c.blocks":"每日区块数","net.c.blocks.cap":"仅统计完整的日期。按目标出块时间，一天有 144 个区块。","net.c.blocks.ref":"目标：每天 144 个区块","net.c.blocks.name":"区块","net.c.finders":"每日区块数，按发现者划分","net.c.finders.cap":"仅统计完整的日期。矿池区块在链上带有矿池名称；只向一个地址付款的区块计为 solo。","net.c.time":"每日平均出块时间","net.c.time.cap":"区块之间相隔的秒数，按日取平均值。","net.c.time.ref":"目标：600 秒","net.c.day":"日期（UTC）","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"谁发现了区块","net.find.p1":"最初几周，每个区块都是 solo 找到的。如今几乎所有区块都来自两个矿池，其中大部分来自一个。","net.find.p2":"这一点很重要。矿池的运营者决定矿池所挖的每个区块包含哪些交易、接在哪个父区块之后，而掌握大部分算力的人能够构建出工作量最多的链。矿池越多、solo 矿工越多，这条链就越难被操纵。","net.find.link":"矿池，以及如何运行你自己的矿池","net.find.title":"已找到区块的占比","net.find.last":"最近 {n} 个区块","net.find.last1000":"截至区块 {h} 的 1,000 个区块","net.find.allb":"截至区块 {h} 的全部区块","net.find.cap":"根据链上数据统计。第一条柱跟随实时的链，另外两条止于页面内置历史数据的末尾。","net.blocks.h":"最新区块","net.blocks.p":"选择一个区块，查看它的区块头、重新计算它的工作量证明并阅读它的交易。","net.blocks.link":"打开区块浏览器","net.blocks.title":"最新的在前","net.b.height":"高度","net.b.age":"发现时间","net.b.by":"发现者","net.b.paid":"支付给","net.b.diff":"难度","net.b.solo":"solo","net.b.addr":"{n} 个地址","net.b.addr.1":"1 个地址","net.src.h":"这些数字从哪里来","net.src.p":"本页面上的数字并非都有同样的分量。","net.src.1.h":"来自链上","net.src.1.p":"高度、难度、供应量以及本页面上的每一张图表。算力是最新区块中的工作量除以它们所花的时间。任何运行全节点的人都可以把这一切重新计算一遍。","net.src.2.h":"自行上报","net.src.2.p":"活跃矿工数、会话数、节点数以及矿池自己声明的算力。这些都是自行上报的数据。它们反映的是趋势，没有人能够核实。","net.src.3.h":"镜像","net.src.3.p":"本页面和区块浏览器读取的是链的一份数据库副本，这样加载更快。镜像会核实它存储的每个区块，但它只是为了方便。真正的链，是全节点达成一致的那一条。","net.src.4.h":"种子节点","net.src.4.p":"新节点首先连接 <code>pool.yskar.app:8646</code> 或 <code>yskar-seed2.dynv6.net:8646</code>。两者由同一位运营者运行。此后，节点之间会互相交换其他节点的地址。","ex.q.label":"在链上搜索","ex.q.go":"搜索","ex.try":"可以从这里开始：","ex.try.0":"区块 0","ex.try.burn":"区块 3,974 中的销毁","ex.try.or":"或","ex.try.zero":"谁也无法花费的地址","ex.crumb":"区块浏览器","ex.msg.empty":"请输入区块高度、区块哈希、交易 ID 或地址。","ex.msg.badAddr":"这个地址有输入错误：它的校验和对不上。请逐个字符核对。","ex.msg.addrShape":"这不是 YSKAR 地址。地址以 ysr1 开头，共 42 个字符。","ex.msg.tooHigh":"区块 {h} 还不存在。链目前在区块 {tip}。","ex.msg.notFound":"链上没有与此匹配的内容。","ex.msg.offlineHash":"链暂时没有响应，所以无法查询这个哈希。请稍后再试。","ex.msg.searching":"正在链上搜索。","ex.msg.badLink":"这个链接没有指向任何区块、交易或地址。","ex.loading":"正在从链上读取。","ex.missing.h":"链暂时没有响应","ex.missing.p":"区块浏览器从 YSKAR 的公开 API 读取每个区块、每笔转账和每个地址，而刚才这次请求失败了。链一旦恢复响应，它会自动重试。","ex.missing.link":"立即重试","ex.none.block":"链上没有区块 {h}。链目前在区块 {tip}。","ex.none.tx":"没有找到带有这个 ID 的交易：它不在任何区块中，也没有在等待打包。如果你是刚刚发送的，本页面会自动再查一次。","ex.back":"返回最新区块","ex.latest.h":"最新区块","ex.latest.snap":"链暂时没有响应。这是上次响应时最新的 {n} 个区块。","ex.latest.live":"从公开 API 读取，每 45 秒刷新一次。","ex.older":"显示更早的区块","ex.older.busy":"读取中","ex.c.height":"高度","ex.c.found":"发现时间","ex.c.by":"发现者","ex.c.transfers":"转账","ex.c.size":"大小","ex.c.hash":"区块哈希","ex.solo":"Solo 矿工","ex.bytes":"{n} 字节","ex.block.h":"区块 {h}","ex.prev":"上一个区块","ex.next":"下一个区块","ex.block.sumPool":"于 {date}（{ago}）由矿池 {who} 找到。","ex.block.sumSolo":"于 {date}（{ago}）由一位 solo 矿工找到。","ex.block.sumGenesis":"链的第一个区块，日期为 {date}。它的奖励进入了一个谁也无法花费的地址。","ex.block.partial":"链暂时没有响应。这是页面此前已经拿到的区块头，所以你仍然可以核对它的工作量证明。链一旦恢复响应，它的交易就会显示出来。","ex.block.values":"区块头里写了什么","ex.block.values.p":"这些数值都打包在上面的 136 个字节里。改动其中任何一个，哈希就不再符合。","ex.f.hash":"区块哈希","ex.f.prev":"上一个区块","ex.f.prev.none":"无。这是第一个区块。","ex.f.merkle":"默克尔根","ex.f.merkle.s":"本区块内交易的指纹","ex.f.state":"状态根","ex.f.state.s":"本区块之后所有余额的指纹","ex.f.diff":"难度","ex.f.diff.s":"平均需要约 {n} 次尝试","ex.f.nonce":"Nonce 与 extranonce","ex.f.nonce.s":"矿工不断变动的两个计数器，直到哈希符合要求","ex.f.size":"大小","ex.f.size.v":"{n} 字节，含 {tx} 笔交易","ex.f.size.v.1":"{n} 字节，含 1 笔交易","ex.txs.h":"本区块中的交易","ex.txs.p":"第一笔交易产生区块奖励。其余每一笔都是由发送方签名的转账。","ex.tx.coinbase":"区块奖励","ex.tx.transfer":"转账","ex.tx.other":"类型为 {type} 的交易","ex.tx.new":"新产生 {a}","ex.tx.newFees":"新产生 {a}，另有手续费 {f}","ex.tx.from":"来自","ex.tx.to":"至","ex.tx.amount":"金额","ex.tx.fee":"手续费","ex.tx.memo":"备注","ex.tx.memoHex":"备注（字节）","ex.tx.nonce":"发送方计数器","ex.tx.nonce.s":"同一地址的每笔转账都带有下一个序号，所以任何一笔都无法被重放","ex.tx.id":"交易 ID","ex.tx.paid":"在区块内直接支付给 {n} 个地址。矿池从未持有过这些币。","ex.tx.c.addr":"地址","ex.tx.c.amount":"金额（YSR）","ex.tx.c.share":"占比","ex.unspendable":"无法花费","ex.txv.sum":"已于 {date} 在区块 {h} 中确认。","ex.txv.block":"区块","ex.txv.until":"有效期至","ex.txv.until.none":"未设置过期高度","ex.txv.until.h":"区块 {h}","ex.txv.size":"大小","ex.txv.raw":"区块中原样记录的字节","ex.txv.raw.p":"节点核对的正是这些字节：签名、发送方余额和计数器。","ex.txv.how":"一笔转账是如何构成的","ex.addr.h":"地址","ex.addr.zero":"没有人持有这个地址的私钥。进入这里的币永远无法再被花费。","ex.addr.balance":"余额","ex.addr.sent":"已发送的转账","ex.addr.first":"首次出现","ex.addr.last":"最近活动","ex.addr.blockN":"区块 {h}","ex.addr.solo":"收到的区块奖励","ex.addr.pool":"收到的矿池支付","ex.addr.hist":"最新动态","ex.addr.more":"最新的 {n} 条记录。","ex.addr.none":"链上还没有这个地址的记录。只要私钥存在，地址就是有效的；链在第一笔付款到来时才会知道它。","ex.h.block":"区块","ex.h.when":"时间","ex.h.what":"类型","ex.h.with":"对方","ex.h.amount":"金额","ex.h.fee":"手续费","ex.k.in":"收到","ex.k.out":"发出","ex.k.reward":"区块奖励","ex.k.pool":"矿池支付","ex.copy.addr":"复制地址","ex.copy.id":"复制 ID","ex.block.sumPoolNoName":"于 {date}（{ago}）由一个矿池找到。","dev.node.h":"运行全节点","dev.node.p":"全节点保存一份自己的链副本，并亲自核对每个区块。它不轻信任何东西，既不轻信其他节点，也不轻信本网站。","dev.node.link":"节点在每个区块中核对什么","dev.node.c1":"获取源代码并构建节点","dev.node.c2":"启动它：连接种子节点，下载整条链，核对每个区块","dev.node.c3":"在第二个终端里，连接你自己的节点挖矿","dev.node.f1.k":"你需要","dev.node.f1.v":"Node.js 22.13 或更高版本，以及 Git。节点使用 Node.js 内置的 SQLite 模块存储链。","dev.node.f2.k":"端口","dev.node.f2.v":"TCP 8646 供其他节点使用，8645 是挖矿程序和钱包使用的 HTTP 接口。","dev.node.f3.k":"时钟","dev.node.f3.v":"请保持系统时钟准确。时间戳比你节点的时钟超前 120 秒以上的区块会被拒绝。","dev.node.f4.k":"种子节点","dev.node.f4.v":"命令行节点没有内置种子节点。请像上面的命令那样，把两个种子节点都写上。","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"应当写在命令里。没有它，节点还会与项目的数据库镜像交换区块，而镜像只接受来自主节点的区块。","dev.node.core":"在 Windows 的 PowerShell 中，请输入 <code>npm.cmd</code> 代替 <code>npm</code>。如果你更喜欢窗口而不是终端，<a href=\"/node#core\">Node Core</a> 可以在 Windows 和 Linux 上运行同样的全节点。","dev.api.h":"通过 HTTP 读取链","dev.api.p":"公开 API 用 JSON 回应普通的 GET 请求。选一个请求，看看它的响应。","dev.api.title":"API 控制台","dev.api.pick":"请求","dev.api.out":"响应","dev.api.run":"重新发送","dev.api.curl":"复制为 curl","dev.api.busy":"正在等待响应。","dev.api.ok":"{status}，用时 {ms} 毫秒，由 www.yskar.app 实时响应。","dev.api.fail":"请求失败（{why}）。这里显示的是本页面上次收到的响应，时间为 {date}。","dev.api.e.summary":"高度、难度、算力、供应量","dev.api.e.blocks":"最新区块，最新的在前","dev.api.e.block":"一个区块及其全部交易","dev.api.e.tx":"按 ID 查询一笔交易","dev.api.e.account":"一个地址的余额和历史","dev.api.e.search":"这段文本是什么类型？","dev.api.e.fees":"一笔转账此刻需要的手续费","dev.api.e.pools":"各矿池及其自行上报的数字","dev.api.e.supply":"已挖出、无法花费和流通中的数量","dev.api.e.circ":"以纯数字给出的流通量","dev.api.n1.h":"只读且开放","dev.api.n1.p":"不需要密钥，也不需要账户。允许跨域请求，因此网页可以直接调用 API。","dev.api.n2.h":"你自己的节点同样可以回应","dev.api.n2.p":"每个全节点都在 8645 端口提供同样的只读路由。把你的代码指向 <code>http://127.0.0.1:8645</code>，就不必依赖任何人的服务器。","dev.api.n3.h":"金额都是整数","dev.api.n3.p":"金额以单位给出：1 YSR 等于 100,000,000 个单位。请把它们当作整数或字符串读取，绝不要当作浮点数。","dev.docs.h":"文档","dev.docs.p":"为想要核实这些说法的人而写。每份文档都链接到它所描述的代码。","dev.docs.v6":"修订版 6 的权威规范，自区块 10,000 起生效。","dev.docs.fullnode":"命令行全节点：命令、选项、HTTP 接口、存储和链重组。","dev.docs.p2p":"节点之间交流所用的协议。","dev.docs.fees":"手续费规则，以及手续费估算是如何得出的。","dev.docs.pool":"矿池：如何加入、如何运行，以及记账方式。","dev.docs.ops":"公开的基础设施：主节点、HTTPS、镜像及其设置。","dev.repo.h":"各部分在哪里","dev.repo.p":"一个代码仓库里包含共识代码、节点、挖矿程序以及守护它们的测试。","dev.repo.core":"共识：区块头、难度、交易、状态、钱包派生","dev.repo.fullnode":"全节点：链、交易池、挖矿接口、只读 API、命令行","dev.repo.p2p":"节点之间的协议","dev.repo.pool":"PPLNS 记账与区块奖励的分配","dev.repo.node":"命令行全节点的构建","dev.repo.nodecore":"适用于 Windows 和 Linux 的 Node Core，包含 GPU 挖矿程序","dev.repo.miner":"命令行挖矿程序，没有任何依赖","dev.repo.observer":"观察者：一个只读的小工具，它下载整条链并重新计算每个区块","dev.repo.tests":"共识、节点、P2P、矿池和钱包的测试","dev.repo.docs":"上面列出的文档","dev.repo.c1":"在代码仓库根目录下：安装、运行测试、检查类型","dev.sign.h":"签名消息","dev.sign.p":"钱包无需移动任何币，就能证明它控制着某个地址。所有 YSKAR 软件都对同一种文本格式进行签名和验证。","dev.sign.1":"签名是对整条消息的原始 UTF-8 字节做的 Ed25519 签名，验证规则与链上相同。","dev.sign.2":"第一行保证了安全：交易是二进制数据，绝不会以这些词开头，因此签名消息永远不可能被当作转账。","dev.sign.3":"YSKAR Wallet 和 Node Core 可以签署这类消息。YSKAR Lab 用它们让你无需密码即可登录。","dev.con.h":"参与贡献与反馈问题","dev.con.1.h":"修改代码","dev.con.1.p":"<a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> 说明了推送之前必须通过哪些检查：类型检查和完整的测试套件。","dev.con.2.h":"想法与提案","dev.con.2.p":"关于协议和软件的提案在 <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a> 公开讨论。使用你的钱包登录。","dev.con.3.h":"安全问题","dev.con.3.p":"请在 <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a> 以 issue 的形式报告。issue 是公开的：描述你看到了什么以及如何复现，绝不要贴出你的 12 个助记词、PIN、钱包文件或私钥。","ysr.now.blocks":"个区块","ysr.bar.circ":"流通量","ysr.bar.burned":"已销毁","ysr.bar.open":"尚未发行","ysr.bar.cap":"在总共可能存在的 21,000,000 YSR 中各自所占的份额。","ysr.sched.title":"按区块高度的发行量","ysr.sched.series":"已发行","ysr.sched.when.past":"已挖出","ysr.sched.when.future":"约在 {date}，按每个区块 600 秒计算","ysr.t.all":"显示全部 37 个纪元","ysr.t.less":"显示前 8 个纪元","ysr.t.now":"当前","ysr.fees.h":"手续费","ysr.fees.p":"一笔转账要向打包它的区块的矿工支付手续费。规则只设定了下限。高于下限时，价格取决于对区块空间的需求。","ysr.fees.f1":"共识规定的下限","ysr.fees.f1.v":"每字节 1 个单位","ysr.fees.f2":"被转发的下限","ysr.fees.f2.v":"每字节 10 个单位。这是节点的一项设置，不是共识规则。","ysr.fees.f3":"一笔 168 字节的普通转账","ysr.fees.f3.v":"此刻的最低值","ysr.fees.f4":"慢速、普通、快速","ysr.fees.f4.v":"只有区块已满时，这三档才有区别。否则，最低手续费就足以进入下一个区块。","ysr.fees.f5":"最小金额","ysr.fees.f5.v":"100 个单位，即 0.000001 YSR","ysr.fees.f6":"正在等待区块的转账","ysr.noprice.h":"没有价格，也没有承诺","ysr.noprice.p1":"YSR 没有价格，没有市场，也没有在任何交易所上线。本网站上没有任何内容承诺这种情况会改变，任何人都不应抱着这样的期待去挖矿。","ysr.noprice.p2":"YSR 拥有的是一套任何人都能核实的规则：固定的上限、公开的发行计划，以及只有持有者的私钥才能动用的币。","tech.header.h":"一个区块以 136 个字节开头","tech.header.p1":"区块头指明它之前的区块，对每笔交易以及区块之后的每个余额作出承诺，并带有矿工找到的 nonce。区块哈希就是对这些字节连续做两次 SHA-256 的结果。","tech.header.p2":"这个长度是特意选定的。SHA-256 以 64 字节为一块进行处理，除 nonce 之外的一切都位于前 128 字节内。矿工每个任务只需把这一部分计算一次；之后的每次尝试只花两步压缩。","tech.pow.h":"任何人都能核实的工作量","tech.pow.p1":"只有当区块的哈希按数字读取时不大于目标值，区块才有效。目标值由难度决定。没有捷径：找到这样的哈希的唯一办法就是逐个尝试 nonce，而核对结果只需要两次哈希计算。","tech.pow.p2":"一个难度单位代表 65,536 次预期尝试。在当前难度 <span class='mono' data-live='difficulty'></span> 下，全网找到一个区块大约需要 <span data-live='attempts'></span> 次尝试。","tech.diff.h":"难度跟随网络变化","tech.diff.p1":"难度在每个区块都根据最近 45 个区块重新计算。较新的区块比较早的区块权重更大，所以当算力加入或离开时，链能很快作出反应。","tech.diff.p2":"每个节点都根据相同的区块算出相同的范围，并拒绝所标难度超出该范围的区块。计算只使用整数，所以两个节点永远不会得出不同的舍入结果。","tech.diff.chart":"自区块 1 以来的难度","tech.diff.cap":"截至区块 <span data-live='snapTip'></span>，每 24 个区块取一次平均值。刻度为对数刻度：每条线是下面一条的十倍。","tech.diff.f1":"窗口","tech.diff.f1.v":"最近 45 个区块，越新的权重越高","tech.diff.f2":"最大步幅","tech.diff.f2.v":"每个区块上调或下调不超过 4 倍","tech.diff.f3":"计入的出块用时","tech.diff.f3.v":"每个区块 1 至 3,600 秒","tech.diff.f4":"紧急规则","tech.diff.f4.v":"超过 1,800 秒没有出块后，要求会按等待时间成比例降低","tech.diff.f5":"时间戳","tech.diff.f5.v":"晚于最近 11 个区块的中位数，且最多比节点时钟超前 120 秒","tech.acc.h":"账户与转账","tech.acc.p1":"YSKAR 为每个地址保存一个余额和一个 nonce。一笔转账写明发送方、接收方、金额和手续费，并用发送方的私钥签名。没有这把私钥，谁也动不了这些币。","tech.acc.p2":"每个区块头中的状态根对全部余额作出承诺。从区块 0 开始重放整条链的节点，要么得到与其他所有节点相同的余额，要么拒绝该区块。","tech.tx.title":"一笔转账，168 字节","tech.tx.p":"外加一条最长 32 字节的可选备注。大小以字节为单位。","tech.tx.aria":"一笔转账的各个字段及其字节大小","tech.tx.f1":"版本与类型","tech.tx.f2":"发送方地址","tech.tx.f3":"接收方地址","tech.tx.f4":"金额","tech.tx.f5":"手续费","tech.tx.f6":"发送方 nonce","tech.tx.f7":"过期高度与备注长度","tech.tx.f8":"公钥","tech.tx.f9":"签名","tech.acc.f1":"只生效一次","tech.acc.f1.v":"nonce 必须等于发送方此前已完成的转账笔数，因此同一笔转账永远不可能被执行两次。","tech.acc.f2":"绑定于本网络","tech.acc.f2.v":"签名涵盖链 ID。为 YSKAR 签名的转账在其他任何地方都无效。","tech.acc.f3":"过期","tech.acc.f3.v":"发送方可以指定一个最后的区块高度。过了这个高度，这笔转账就永远不会被打包。","tech.acc.f4":"备注","tech.acc.f4.v":"最长 32 字节，公开存储在链上。","tech.acc.f5":"最低手续费","tech.acc.f5.v":"共识规定每字节 1 个单位。节点只转发每字节 10 个单位起的转账。手续费归该区块的矿工所有。","tech.acc.f6":"一笔普通转账的费用","tech.acc.f6.v":"此刻至少","tech.key.aria":"从 12 个助记词到一个地址","tech.key.1":"助记词","tech.key.2":"派生路径","tech.key.3":"密钥对","tech.key.4":"地址","tech.key.p":"一个钱包就是 12 个或 24 个助记词（BIP39）。私钥在设备上由它们派生出来（SLIP-0010），地址则是公钥 SHA-256 哈希的前 20 个字节，以 bech32m 格式写出。助记词永远不会离开生成它们的设备。","tech.nodes.h":"每个节点都核对每个区块","tech.nodes.p1":"全节点保存整条链，只有在把一个区块完整核对之后才会接受它，无论这个区块来自其他节点还是来自它自己的挖矿程序。各项检查按以下顺序进行。","tech.nodes.link":"运行全节点","tech.check.1":"版本、最多 2,000 笔交易、排在首位且仅有一笔的奖励交易，以及交易根。","tech.check.2":"对区块头连续做两次哈希，结果不大于所标难度对应的目标值。","tech.check.3":"高度等于父区块的高度加一，前一个哈希就是父区块的哈希。","tech.check.4":"晚于最近 11 个区块的中位数，不早于父区块，且最多比节点时钟超前 120 秒。","tech.check.5":"所标难度落在由此前区块推算出的范围之内。","tech.check.6":"每笔转账的签名、发送方、nonce、余额、手续费和过期高度。奖励交易支付的金额恰好等于区块奖励加上手续费。","tech.check.7":"区块之后对全部账户计算出的根，等于区块头中的状态根。","tech.nodes.chain.h":"以哪条链为准","tech.nodes.chain.p":"累计工作量最多的有效链，其中一个区块的工作量就是它的难度。节点会保留相互竞争的区块，当另一个分支的工作量更多时就切换过去。","tech.nodes.pool.h":"无托管的矿池","tech.nodes.pool.p":"一个区块的奖励交易最多可以向 64 个地址付款。矿池的记账结果直接成为这笔交易，因此由链直接向每位矿工付款，运营者从不持有任何人的币。<a href='/mining#pools'>矿池如何运作</a>","tech.rev.h":"规则在某个区块高度上变更","tech.rev.p":"每一次规则变更都会连同它开始生效的高度一起写进代码。所有节点在同一个区块切换，而低于该高度的每个区块都逐字节保持原有规则。","tech.rev.c1":"修订版","tech.rev.c2":"起始区块","tech.rev.c3":"变更内容","tech.rev.c4":"状态","tech.rev.2":"奖励交易可以向多个地址付款。矿池正是建立在这一点之上。","tech.rev.3":"按字节计算的最低手续费取代了固定手续费，并开始适用最小金额。","tech.rev.4":"难度字段可以容纳任意大小的数值。","tech.rev.5":"对时间戳、区块编码和奖励交易采用更严格的规则。","tech.rev.6":"共享账户、时间锁和哈希锁、批量付款、新的状态树以及更高的上限。","tech.rev.note":"修订版 2 到 5 是对规则的修正和收紧。修订版 6 是第一个增加新能力的修订版，也是第一个旧节点无法跟随的修订版。","tech.v6.h":"修订版 6","tech.v6.p":"下一次规则变更从区块 10,000 开始。社区在 2026年10月25日的投票中选定了这个高度。它改变了账户记录、地址格式和交易格式，让账户不只是保存余额。","tech.v6.count":"区块 10,000","tech.v6.spec":"阅读修订版 6 的规范","tech.v6.1.h":"共享账户","tech.v6.1.p":"需要多个签名才能支出的账户，例如 3 选 2，最多支持 16 个密钥。适用于共同资金和更安全的储蓄。","tech.v6.2.h":"时间锁","tech.v6.2.p":"只有从指定区块高度起才能支出的 YSR。","tech.v6.3.h":"哈希锁","tech.v6.3.p":"付款只有在对方出示一个秘密值后才会释放，超过设定高度后则退回给发送方。双方无需相互信任即可交易。","tech.v6.4.h":"批量付款","tech.v6.4.p":"一笔交易可同时向最多 1,000 个收款方付款。","tech.v6.5.h":"每个区块容量更大","tech.v6.5.p":"每个区块最多 5,000 笔交易（原为 2,000 笔），矿池的区块最多可向 255 个地址付款（原为 64 个）。","tech.v6.6.h":"为以后打下基础","tech.v6.6.p":"为成千上万个账户设计的状态树、带版本号的地址，以及每个签名中的分叉标识。","tech.v6.same.h":"保持不变的内容","tech.v6.same.1":"2100 万 YSR 和减半计划","tech.v6.same.2":"10 分钟出块、SHA-256 和难度规则","tech.v6.same.3":"每个地址、每把私钥和每个余额","tech.v6.do.h":"你需要做什么","tech.v6.do.1":"在区块 10,000 之前更新你的钱包和节点","tech.v6.do.2":"挖矿程序、GPU 挖矿程序和 HiveOS 软件包无需更新","tech.v6.do.3":"未更新的钱包仍然可以收到 YSR，但在更新之前无法发送","tech.lim.h":"已知的局限","tech.lim.p":"系统目前无法防范的情况。这份清单出自项目自己的安全文档。","tech.lim.link":"完整的安全模型","tech.lim.1.h":"网络规模小","tech.lim.1.p":"网络有两个种子节点，都由同一位运营者运行。只有在没有任何一方掌握大部分算力的情况下，工作量证明才能保护一条链，而通过某个矿池挖矿的算力由该矿池的运营者支配。","tech.lim.2.h":"没有检查点","tech.lim.2.p":"节点会切换到任何一条工作量更多的有效链，无论它从多早的位置分叉。一笔转账之上叠加的区块越多，就越可以把它视为最终确定。","tech.lim.3.h":"区块浏览器的数据来源","tech.lim.3.p":"区块浏览器和各应用读取的是镜像，也就是为了速度而保留的一份链的数据库副本。它只是为了方便，并不是权威：真正的链，是全节点达成一致的那一条。","tech.lim.4.h":"矿池名额","tech.lim.4.p":"一个矿池最多有 64 个名额，收取手续费时为 63 个；从修订版 6 起分别为 255 个和 254 个。开启会话只需要一个有效地址，因此名额可以被人以很低的成本占满。","tech.lim.5.h":"开放的接口","tech.lim.5.p":"节点的 HTTP 接口不会限制每个客户端的请求数量。在公开的节点上，这件事必须由反向代理来做。","tech.docs.1":"协议规范：格式、哈希、难度、有效性规则和测试向量。","tech.docs.3":"密码学和共识强制保证了什么，你必须信任什么，以及已知的局限。","miner.title":"亲自寻找一个 nonce","miner.state":"在你的浏览器中运行","miner.intro":"你的浏览器取出最新区块的区块头，针对一个更容易的目标值尝试各种 nonce。真正的目标值远远超出浏览器所能达到的范围。","miner.bits":"哈希开头必须为零的位数","miner.odds":"{b} 位：大约每 {n} 个哈希中有 1 个","miner.start":"开始搜索","miner.stop":"停止","miner.attempts":"尝试次数","miner.speed":"速度","miner.time":"用时","miner.nonce":"找到的 nonce","miner.hash":"最后尝试的哈希","miner.hashFound":"找到的哈希","miner.target":"本演示的目标值","miner.found":"尝试 {n} 次后找到。","miner.none":"尝试了 {n} 次，没有找到低于目标值的哈希。重新开始，或者减少要求的零位数。","miner.stopped":"尝试 {n} 次后已停止。","miner.real":"以 {r} 的速度，在今天的难度下，这个浏览器平均需要大约 {t} 才能找到一个真正的区块。","field.version":"版本","field.version.d":"区块头的版本。目前为 1，随着共识修订版 6 将变为 6。","field.height":"高度","field.height.d":"本区块的编号，从区块 0 开始计数。","field.prev":"前一个哈希","field.prev.d":"上一个区块的哈希。它把区块串成链：改动任何一个旧区块，都会改变它之后的每一个哈希。","field.merkle":"交易根","field.merkle.d":"对区块内全部交易计算出的一个哈希。其中任何一笔交易哪怕只改动一个字节，它都会改变。","field.state":"状态根","field.state.d":"对本区块之后的每个余额和 nonce 计算出的一个哈希。每个节点都自行计算并进行比对。","field.time":"时间戳","field.time.d":"矿工构建该区块的时间。它必须晚于最近 11 个区块的中位数。","field.diff":"难度","field.diff.d":"这个区块必须达到的难度。目标值由它得出：2^240 除以难度。","field.count":"交易数量","field.count.d":"区块中包含多少笔交易，其中也包括支付奖励的那一笔。","field.extra":"Extranonce","field.extra.d":"节点分配给每位矿工的一个数值，这样两位矿工就永远不会搜索相同的区块头。","field.nonce":"Nonce","field.nonce.d":"矿工不断变换的数字，直到哈希低于目标值。两次尝试之间，除此之外什么都不变。","proof.fixedBlock":"已固定在链上","proof.block":"区块 {h}","proof.found":"{ago}找到","proof.fixed":"自 2026年9月9日起未变","proof.cap":"区块头：136 个字节，分为十个字段。","proof.bytesLabel":"区块 {h} 区块头的 136 个字节（十六进制）","proof.range":"第 {a} 至 {b} 字节","proof.first":"136 个字节的 SHA-256","proof.hash":"连续做两次 SHA-256：区块哈希","proof.target":"难度为 {d} 时的目标值","proof.valid":"有效。哈希低于目标值。","proof.invalid":"无效。哈希高于目标值。","proof.time":"在你的浏览器中用 {ms} 毫秒算出。","proof.again":"再检查一次","proof.genesis":"验证区块 0","proof.latest":"验证最新区块","proof.open":"在区块浏览器中打开此区块","check.1":"结构","check.2":"工作量证明","check.3":"在链上的位置","check.4":"时间戳","check.5":"难度","check.6":"每笔交易","check.7":"状态根","chart.asTable":"以表格显示数值","chart.total":"合计","chart.height":"截至区块","n.2000":"2,000","n.4000":"4,000","n.6000":"6,000","n.7000":"7,000","n.10000":"10,000","rev.active":"自 {date} 起生效","rev.set":"已确定，还有 {n} 个区块","ms.done":"已生效","home.how.1.h":"矿工搜索","home.how.1.p":"手机、电脑和显卡一遍又一遍地对区块头做哈希，每次换一个不同的 nonce。只要有一个哈希低于目标值，区块就有效。","home.how.2.h":"节点核对","home.how.2.p":"每个全节点都从区块 0 开始，重新计算工作量、签名和所有余额。违反规则的区块会被拒绝，无论它是谁发来的。","home.how.3.h":"区块付款","home.how.3.p":"奖励由区块本身支付：要么全部付给找到它的人，要么在矿池的矿工之间分配，直接打到各自的地址。矿池从不持有任何人的币。","dev.api.down":"请求失败（{why}）。API 此刻从这里无法得到响应。"};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("zh");
